  "Todavía no hay mapas en este mundo. Crea uno y sube tu propia imagen, o genérala con IA; después podrás calibrar su escala y clavar en él los lugares que ya has guardado.": "この世界にはまだ地図がありません。画像を作成して独自の画像をアップロードするか、AI で生成します。次に、そのスケールを調整し、すでに保存した場所にピンを付けることができます。",
  "Un mapa puede ser el mapa de un lugar concreto. No hace falta: un mapa de rutas cruza cinco reinos y no es de ninguno.": "地図は特定の場所の地図である場合があります。そうである必要はありません。貿易ルートの地図は5つの王国を横断し、どの王国にも属しません。",
  "Al crearlo podrás subir tu propia imagen. Después se calibra la escala y se clavan encima los lugares que ya tengas guardados.": "作成したら、独自の画像をアップロードできます。次に、スケールを調整し、すでにある場所をピンで固定します。",
  "Mundo": "世界",
  "Interior": "インテリア",
  "Mazmorra": "ダンジョン",
  "Traduce texto, documentos y adjuntos de Zotero con el modelo que elijas, incluido un modo PDF facsímil.": "PDF ファクシミリモードを含む、選択したモデルでテキスト、ドキュメント、Zotero 添付ファイルを翻訳します。",
  "Traducir texto, documentos y adjuntos de Zotero con el modelo elegido, conservando la estructura de DOCX y EPUB y la apariencia de los PDF mediante un modo facsímil.": "選択したモデルを使用してテキスト、ドキュメント、Zotero 添付ファイルを翻訳し、DOCX および EPUB 構造とファクシミリモードによる PDF の外観を保持します。",
  "Mover documento a la papelera": "文書をゴミ箱に移動する",
  "Mover documentos a la papelera": "ドキュメントをゴミ箱に移動する",
  "«{name}» dejará de aparecer. Podrás recuperarlo desde la administración de datos.": "「{name}」は表示されなくなります。データ管理から復元できます。",
  "Los {n} documentos seleccionados dejarán de aparecer. Podrás recuperarlos desde la administración de datos.": "{n} 個の選択したドキュメントは表示されなくなります。データ管理から復元できます。",
  "¿Eliminar también las ideas vinculadas?": "リンクされたアイデアも削除しますか?",
  "Se eliminarán las ideas que solo proceden de estos documentos, junto con sus embeddings, evidencia y conexiones. Las ideas compartidas con otras fuentes se conservarán.": "これらの文書のみから得られたアイデアは、その埋め込み、証拠、関連性とともに削除されます。他の情報源と共有されたアイデアは保持されます。",
  "Eliminar ideas y embeddings": "アイデアと埋め込みを削除する",
  "Conservar ideas": "アイデアを保存する",
  "Cancelar operación": "操作をキャンセルする",
  "Eliminar idea": "アイデアの削除",
  "Se eliminará «{name}» junto con su embedding, evidencia y conexiones. Esta acción no se puede deshacer.": "「{name}」は、その埋め込み、証拠、接続とともに削除されます。この操作は元に戻すことができません。",
  "Seleccionar o desplazar": "選択またはスクロール",
  "Editar o eliminar": "編集または削除",
  "¿Eliminar esta anotación? No se puede deshacer.": "この注釈を削除しますか?これを元に戻すことはできません。",
  "Suelta los archivos para añadirlos a esta sección": "ファイルをドロップしてこのセクションに追加します",
  "Se importarán como materiales en la selección actual.": "これらは、現在の選択範囲にマテリアルとしてインポートされます。",
  "No se pudo traducir este mensaje.": "このメッセージは翻訳できませんでした。",
  "Analizando fragmento {current}/{total} con IA… ({seconds}s)": "AI を使用してチャンク {current}/{total} を分析しています… ({seconds} 秒)",
  "Analizando fragmento {current}/{total} con IA…": "チャンク {current}/{total} を AI で分析中…",
  "Fusionando idea {current}/{total}…": "アイデア {current}/{total} を結合しています…",
  "Extrayendo p. {current}/{total}": "p.11を抜粋します。 {current}/{total}",
  "{candidates} candidatos encontrados ({cross} entre temas)": "{candidates} 件の候補が見つかりました (テーマ全体で {cross} 件)",
  "{n} nuevas relaciones": "{n} 新しい関係",
  "{added} nuevas · {validated} validados · {scanned} escaneados": "{added} 新規 · {validated} 検証済み · {scanned} スキャン済み",
  "Reintentando ({current}/{total})…": "再試行中 ({current}/{total})…",
  "Lecturas fundamentales": "基礎的な読み物",
  "Base conceptual y dependencias intelectuales que conviene leer antes de avanzar.": "先に進む前に読んでおくべき概念的な基礎と知的依存関係。",
  "Textos más útiles para cubrir o delimitar huecos detectados en el corpus.": "コーパス内で検出されたギャップをカバーまたは定義するのに最も役立つテキスト。",
  "Ampliación de temas secundarios": "二次テーマの拡充",
  "Lecturas que amplían temas del proyecto sin saturar una sola línea temática.": "一行の探求を過負荷にすることなく、プロジェクトのテーマを拡張する読書。",
  "Contrastar ideas o contradicciones": "アイデアや矛盾を比較する",
  "Documentos conectados con relaciones, refutaciones o contradicciones ya analizadas.": "すでに分析された関係、反論、または矛盾に関連する文書。",
  "Lecturas pendientes de análisis": "分析待ちの測定値",
  "Ítems no leídos o poco procesados que conviene analizar para decidir si entran al mapa.": "マップ上に属するかどうかを決定する前に分析する、未読のアイテムまたは軽く処理されたアイテム。",
  "Leídas sin incorporar al mapa": "読み取りましたが、マップには追加されませんでした",
  "Obras marcadas como leídas en Zotero pero todavía sin análisis profundo suficiente.": "Zotero で既読としてマークされているが、まだ十分な深い分析が不足している作品。",
  "Siguientes mejores opciones": "次善の選択肢",
  "Lecturas restantes que todavía aportan señales relevantes para el criterio elegido.": "選択した基準に関連するシグナルを依然として提供する残りの読み取り値。",
