  "Finalizando claves de cita y cola de extracción…": "引用キーと抽出キューを終了しています…",
  "Importación de Zotero completada y verificada.": "Zotero のインポートが完了し、検証されました。",
  "Importación cancelada; el catálogo ya importado se conserva.": "インポートはキャンセルされました。インポート済みのカタログは保持されます。",
  "No hay obras con análisis profundo para indexar.": "インデックスに登録するほど深い分析を行った作品はありません。",
  "No hay obras disponibles para indexar.": "インデックスに登録できる作品はありません。",
  "La obra ya no existe.": "その作品はもう存在しません。",
  "No se puede cambiar de bóveda con la cola de análisis activa. Pausa o termina los trabajos pendientes antes de cargar otra bóveda.": "分析キューがアクティブな間はVaultを切り替えることはできません。別のVaultをロードする前に、保留中のジョブを一時停止または終了します。",
  "No se puede cambiar de bóveda mientras se están indexando embeddings de ideas.": "アイデアの埋め込みのインデックス作成中にVaultを切り替えることはできません。",
  "No se puede cambiar de bóveda mientras se están indexando pasajes.": "パッセージのインデックス作成中はVaultを切り替えることはできません。",
  "No se puede cambiar de bóveda mientras se descubren relaciones semánticas.": "セマンティック関係が検出されている間は、Vaultを切り替えることはできません。",
  "Bóveda no encontrada.": "Vaultが見つかりません。",
  "No se encontró la bóveda de origen de las claves API.": "API キーのソースVaultが見つかりませんでした。",
  "Esta bóveda ya está cargada.": "このVaultはすでにロードされています。",
  "Bóveda cargada.": "Vaultがロードされました。",
  "Claves API copiadas: {n}.": "コピーされた API キー: {n}。",
  "En cola": "キューに入れられました",
  "Cola y tareas": "キューとタスク",
  "Limpiar terminadas": "クリア済み",
  "Limpiar tareas terminadas": "終わったタスクをクリアする",
  "Se ocultarán de la cola las tareas completadas, canceladas o fallidas. Se conservarán las tareas en curso, pendientes o en pausa y los documentos generados.": "完了、キャンセル、または失敗したタスクはキューから非表示になります。実行中、保留中、または一時停止されたタスクと生成されたドキュメントは保持されます。",
  "Extracción de texto": "テキスト抽出",
  "Sin tareas ni colas en curso.": "進行中のタスクやキューはありません。",
  "Fallido": "失敗した",
  "Cancelado": "キャンセル",
  "Pausado": "一時停止中",
  "Ruta optimizada por {strategy}: {shown} lecturas priorizadas de {total} obras, agrupadas en fases manejables.": "{strategy} 用に最適化されたパス: {total} 件の作品から優先度の高い {shown} 件の読書を、扱いやすいフェーズにグループ化しました。",
  "Marcada como leída por la etiqueta de Zotero.": "Zotero タグによって既読としてマークされます。",
  "Pendiente de lectura.": "読書を待っています。",
  "{n} idea(s) extraída(s).": "{n} 個のアイデアが抽出されました。",
  "{n} tema(s) detectado(s).": "{n} 個のテーマが検出されました。",
  "{n} contradicción(es) o refutación(es).": "{n} の矛盾または反論。",
  "{n} hueco(s) asociado(s).": "{n} 個の関連ギャップ。",
  "Alta conexión con huecos de investigación.": "研究ギャップとの強いつながり。",
  "Posible texto de base.": "潜在的な基礎テキスト。",
  "Posible texto de base ({n} cita(s) internas aproximadas).": "潜在的な基礎テキスト ({n} のおおよその内部引用)。",
  "Conecta varias líneas temáticas o relaciones del grafo.": "複数の主題の線またはグラフの関係を接続します。",
  "Autoría conectada con otros nodos del corpus.": "他のコーパスノードに接続された著者名。",
  "Aporta actualización reciente.": "最近のアップデートを提供します。",
  "Coincide con las prioridades indicadas.": "指定された優先順位と一致します。",
  "Conviene completar análisis antes de decidir su papel en el mapa.": "マップ上での役割を決定する前に、分析を完了してください。",
  "Notas rápidas": "簡単なメモ",
  "Nueva nota": "新しいメモ",
  "Título (opcional)": "タイトル (オプション)",
  "Tachado": "取り消し線",
  "Borrar nota": "メモを削除する",
