  "Buscar en tus notas…": "メモを検索してください…",
  "Aún no tienes notas. Crea la primera con el botón +.": "まだメモはありません。 + ボタンを使用して最初のものを作成します。",
  "Sin guardar": "未保存",
  "apuntes rápidos en Markdown, siempre a mano.": "Markdown の簡単なメモをいつでも手の届くところに。",
  "Modelo de embeddings": "埋め込みモデル",
  "El modelo local seleccionado ya no está disponible.": "選択したローカルモデルは使用できなくなりました。",
  "Preparando el motor local…": "ローカルランタイムを準備しています…",
  "Descargando {model}…": "{model} をダウンロード中…",
  "Descarga cancelada.": "ダウンロードがキャンセルされました。",
  "Descarga detenida. Los archivos temporales se han eliminado.": "ダウンロードが停止されました。一時ファイルが削除されました。",
