  "Ponle un título a la rúbrica.": "ルーブリックにタイトルを付けます。",
  "Una rúbrica necesita al menos dos niveles de desempeño.": "ルーブリックには少なくとも2つのパフォーマンスレベルが必要です。",
  "Añade al menos un criterio de evaluación.": "少なくとも1つの評価基準を追加します。",
