  "Cada criterio necesita un nombre.": "すべての基準には名前が必要です。",
  "Hay niveles con la misma puntuación: no se podrán distinguir al calificar.": "一部のレベルは同じスコアを共有します。採点時にそれらを区別することはできません。",
  "Este criterio no tiene ningún descriptor escrito.": "この基準には記述子が書かれていません。",
  "Faltan descriptores en algunos niveles de este criterio.": "この基準の一部のレベルには記述子がありません。",
  "Los pesos de los criterios no suman 100 %.": "基準の重みを合計しても100% にはなりません。",
  "Con más de 6 criterios la rúbrica se vuelve difícil de aplicar en clase.": "6つの基準を超えると、ルーブリックを実際に授業に適用することが難しくなります。",
  "Más de 5 niveles aparenta una precisión que no se sostiene al corregir.": "5レベルを超えると、マーキング時に精度が維持できないことを示します。",
  "Este criterio parece un requisito de entrega, no una cualidad del trabajo.": "これは作品の品質ではなく、提出要件のようです。",
  "Este criterio junta dos aspectos: sepáralos para poder evaluarlos por separado.": "この基準は2つの側面をまとめたもので、それぞれを個別に判断できるように分割します。",
  "Este descriptor solo emite un juicio: describe qué hace el trabajo.": "この記述子は判断を下すだけです。作業が実際に何を行うかを説明します。",
  "Este descriptor describe carencias: redáctalo en positivo, por lo que el trabajo sí hace.": "この記述子は何が欠けているかを説明します。作業が何を行うかを中心に書き直します。",
  "Estos dos niveles solo se diferencian en matices: ¿qué hace distinto el trabajo?": "これら2つのレベルの違いはシェーディングだけです。作業の違いは何でしょうか?",
  "Dos niveles repiten el mismo descriptor.": "2つのレベルが同じ記述子を繰り返します。",
  "Los descriptores de este criterio tienen longitudes muy dispares: mantén una estructura paralela.": "この行の記述子は長さが大幅に異なるため、並列に保ちます。",
  "Las puntuaciones no descienden de mayor a menor desempeño.": "スコアは最高レベルから最低レベルまで下がりません。",
  "Crea rúbricas de evaluación por criterios y niveles, con ayuda de la IA.": "AI の助けを借りて、基準とレベルに応じた評価ルーブリックを作成します。",
