  "Personas, relaciones, identidades y evidencias biográficas para investigación histórica.": "人物、関係、アイデンティティ、歴史研究のための伝記的証拠。",
  "Nuevos ámbitos con especialistas, colaboración activa y testers.": "スペシャリスト、積極的なコラボレーション、テスターに​​よる新しい分野。",
