  "Busca coincidencias en otras bóvedas y, si encuentra ideas, embeddings, resúmenes o pasajes ya generados, los importa antes de usar IA.": "他のVault内で一致するものを探し、すでに生成されているアイデア、埋め込み、要約、または文章が見つかった場合は、AI を使用する前にそれらをインポートします。",
  "Análisis reutilizado desde otras bóvedas para {n} obra(s).": "{n} 個の作業に対して他の Vault から分析が再利用されました。",
  "{n} documento(s) añadidos; {reused} componente(s) reutilizados con huellas exactas.": "{n} 個のドキュメントが追加されました。 {reused} コンポーネントが正確なフィンガープリントで再利用されました。",
  "No se encontró análisis reutilizable en otras bóvedas para la selección.": "選択した他のVaultでは再利用可能な分析が見つかりませんでした。",
  "Zona peligrosa": "危険地帯",
  "Vault objetivo": "ターゲットVault",
  "Reinicializar": "リセット",
  "La bóveda activa no se puede eliminar. Carga otra bóveda antes.": "アクティブなVaultは削除できません。まず別のVaultをロードします。",
  "La bóveda principal no se puede eliminar; puedes reinicializarla.": "プライマリVaultは削除できません。代わりにリセットすることもできます。",
  "Eliminar bóveda": "Vaultの削除",
  "Reinicializar bóveda": "Vaultをリセットする",
  "Esta acción eliminará la bóveda \"{name}\" y sus archivos locales. No afecta a otras bóvedas.": "これにより、Vault \"{name}\" とそのローカルファイルが削除されます。他のVaultには影響しません。",
  "Esta acción borrará el contenido de \"{name}\" y recreará su base de datos vacía. No afecta a otras bóvedas.": "これにより、「{name}」の内容が消去され、空のデータベースが再作成されます。他のVaultには影響しません。",
  "Continuar": "続く",
  "Introduce este código manualmente": "このコードを手動で入力してください",
  "Introduce este código manualmente para eliminar la bóveda \"{name}\".": "Vault「{name}」を削除するには、このコードを手動で入力します。",
  "Código de seguridad": "セキュリティコード",
  "No se puede pegar aquí. Escribe las cuatro cifras manualmente.": "ここに貼り付けることはできません。 4桁の数字を手動で入力します。",
  "Código incorrecto.": "コードが間違っています。",
