  "Código correcto. Confirma una última vez para ejecutar la acción.": "コードが受け入れられました。最後にもう一度確認してアクションを実行します。",
  "Código correcto. Confirma una última vez para eliminar la bóveda \"{name}\".": "コードが受け入れられました。最後にもう一度確認して、Vault「{name}」を削除します。",
