  "Aprendizaje y materiales de estudio.": "学習および学習教材。",
  "Tablas, datos y análisis.": "表、データ、分析。",
  "Archivos y fuentes históricas.": "アーカイブと歴史的資料。",
  "Entrevistas, historia oral y periodismo.": "インタビュー、オーラルヒストリー、ジャーナリズム。",
  "Mundos, personajes y narrativas.": "世界観、キャラクター、そして物語。",
  "Cursos, evaluación y materiales.": "コース、評価、教材。",
  "Creación de mundos para escritores.": "作家のための世界構築。",
  "Clases, cursos y materiales; la IA solo verá placeholders del alumnado.": "クラス、コース、教材。 AI は学生のプレースホルダーのみを認識します。",
  "Vista previa navegable. Puedes crear el vault y consultar sus secciones, pero todavía no contienen funciones.": "ナビゲート可能なプレビュー。Vaultを作成してそのセクションを参照することはできますが、これらのセクションにはまだ機能が含まれていません。",
  "Este vault es una preview navegable: se creará normalmente, pero por ahora sus secciones son solo una muestra y no permiten realizar acciones.": "この Vault はナビゲート可能なプレビューです。通常どおりに作成されますが、現時点ではそのセクションは単なるショーケースであり、アクションは許可されません。",
  "Este vault muestra la estructura prevista. Sus secciones todavía no permiten realizar acciones.": "このVaultは計画された構造を示しています。そのセクションではまだアクションを許可していません。",
  "Disponible próximamente": "近日発売予定",
