  "Activado, todas las bóvedas comparten la paleta. Desactivado, cada una recuerda la suya y las nuevas empiezan con la predeterminada. El modo claro u oscuro es común en ambos casos.": "オンでは、すべてのVaultがパレットを共有します。オフの場合、各Vaultは独自のVaultを保持し、新しいVaultはデフォルトのVaultで開始されます。ライトモードまたはダークモードはどちらの方法でも共有されます。",
