  "Beta updates": "ベータ版のアップデート",
  "Recibe versiones de prueba además de las actualizaciones estables. Es una opción voluntaria y está desactivada de forma predeterminada.": "安定したアップデートに加えて、テストビルドを受け取ります。これはオプションであり、デフォルトでは無効になっています。",
  "Antes de instalar una beta, Nodus exige una copia completa y verificada en tu carpeta de Recuperación.": "ベータ版をインストールする前に、Nodus では Recovery フォルダーに完全な検証済みのバックアップが必要です。",
  "Activadas": "有効",
  "Desactivadas": "無効",
  "¿Activar Beta updates?": "ベータ版アップデートを有効にしますか?",
  "Este canal está recomendado únicamente para testers.": "このチャンネルはテスターのみに推奨されます。",
  "Las versiones beta pueden contener errores o ser inestables.": "ベータ版にはバグが含まれているか、不安定である可能性があります。",
  "Si continúas, Nodus comprobará y recibirá versiones beta además de las actualizaciones estables.": "続行すると、Nodus は安定したアップデートに加えてベータ版をチェックして受け取ります。",
  "Antes de instalar una beta, Nodus creará y verificará una copia completa. Si Recuperación no está configurada o la copia falla, la beta no se instalará.": "ベータ版をインストールする前に、Nodus は完全なバックアップを作成して検証します。リカバリが構成されていない場合、またはバックアップが失敗した場合、ベータ版はインストールされません。",
  "Creando y verificando una copia de seguridad antes de actualizar…": "更新する前にバックアップを作成して確認しています…",
  "Configura Recuperación antes de instalar una beta. La actualización permanece descargada y tus datos no se han modificado.": "ベータ版をインストールする前にリカバリをセットアップします。アップデートはダウンロードされたままになり、データは変更されません。",
  "La beta no se instaló porque no pudo crearse y verificarse la copia de seguridad previa. Tus datos no se han modificado.": "アップデート前のバックアップを作成および検証できなかったため、ベータ版はインストールされませんでした。データは変更されていません。",
  "Protegiendo tus datos": "データの保護",
  "Nodus está creando y verificando una copia completa antes de instalar la actualización.": "Nodus は、アップデートをインストールする前に完全なバックアップを作成して検証しています。",
