  "Comprobación no disponible": "更新チェックは利用できません",
  "Las actualizaciones se comprueban automáticamente en la aplicación instalada.": "アップデートは、インストールされたアプリケーションで自動的にチェックされます。",
  "Comprobamos automáticamente que tengas la versión más reciente y segura de Nodus.": "Nodus が最新かつ最も安全なバージョンであることを自動的に確認します。",
