  "Activar servidor MCP": "MCPサーバーを有効にする",
  "Copiloto de escritura (Word)": "副操縦士の執筆 (Word)",
  "1) Genera el certificado local · 2) Activa el copiloto · 3) Instálalo en Word y ábrelo desde la pestaña Nodus.": "1) ローカル証明書を生成します · 2) コパイロットを有効にします · 3) Word にインストールし、[Nodus] タブから開きます。",
  "Activar copiloto para Word": "Word コパイロットを有効にする",
  "Activar Nodus Copilot para Word": "Word の Nodus Copilot を有効にする",
  "Generar certificado": "証明書の生成",
  "Certificado listo": "証明書の準備ができました",
  "Instalando…": "インストール中…",
  "Instalar/actualizar en Word": "Word でのインストール/更新",
  "Token del copiloto regenerado.": "副操縦士トークンが再生成されました。",
  "Sirve el complemento de Word en https://localhost y busca relaciones del párrafo con tu biblioteca. Carga el manifiesto (word-addin/manifest.xml) en Word para usarlo.": "https://localhost 経由で Word アドインを提供し、段落がライブラリにどのように関連しているかを検索します。 word-addin/manifest.xml を Word にサイドロードして使用します。",
  "Sirve Nodus Copilot en https://localhost, busca ideas del corpus, muestra conexiones y permite insertar una idea con la IA configurada en Nodus.": "https://localhost 上で Nodus Copilot を提供し、コーパスのアイデアを検索し、接続を表示し、Nodus で構成された AI とのアイデアを挿入します。",
  "Copiloto de escritura (LibreOffice)": "副操縦士の作成 (LibreOffice)",
  "Instalar macro en LibreOffice": "LibreOfficeマクロをインストールする",
  "Copia el macro nodus_copilot.py en la carpeta de macros de LibreOffice. Para usarlo en LibreOffice Writer, ve a Herramientas -> Macros -> Ejecutar macro -> Mis macros -> nodus_copilot -> start_nodus_copilot.": "nodus_copilot.py マクロを LibreOffice マクロフォルダーにコピーします。 LibreOffice Writer で使用するには、[ツール] -> [マクロ] -> [マクロの実行] -> [マイマクロ] -> [nodus_copilot] -> [start_nodus_copilot] に移動します。",
  "Ayuda para conectar un cliente MCP": "MCP クライアントの接続に関するヘルプ",
  "Puerto local": "ローカルポート",
  "Activo": "アクティブ",
  "Error del servidor MCP": "MCPサーバーエラー",
  "Apagado": "オフ",
  "Ver datos de conexión": "接続の詳細を表示する",
  "Regenerar token": "トークンを再生成する",
  "Solo escucha en este ordenador. Las herramientas de escritura están activas mientras el servidor esté encendido.": "このコンピュータでのみ聴取されます。書き込みツールは、サーバーの電源が入っている間はアクティブになります。",
  "Token MCP regenerado. Reconecta los clientes con el nuevo token.": "MCPトークンが再生成されました。新しいトークンを使用してクライアントを再接続します。",
  "Conectar un cliente MCP": "MCP クライアントを接続する",
  "Usa la URL y el bearer token actuales. No necesitas claves adicionales.": "現在の URL とベアラートークンを使用します。追加のキーは必要ありません。",
  "URL del servidor": "サーバーURL",
  "Bearer token": "無記名トークン",
  "Activa el servidor para generar un token.": "サーバーがトークンを生成できるようにします。",
  "Si tu versión permite conectores MCP remotos, añade la URL y la cabecera de autorización. Como alternativa compatible, usa este puente stdio y reinicia Claude Desktop:": "ご使用のバージョンがリモート MCP コネクタをサポートしている場合は、URL と認証ヘッダーを追加します。互換性のある代替手段として、この stdio ブリッジを使用し、Claude Desktop を再起動します。",
  "Añade un servidor MCP con esta URL y la cabecera de autorización en Connectors/Developer mode. ChatGPT web no puede acceder a 127.0.0.1: necesitarías un túnel HTTPS externo, que no forma parte de Nodus. Si expones el servidor, protege el token.": "コネクタ/開発者モードで、この URL と認証ヘッダーを使用して MCP サーバーを追加します。 ChatGPT Web は127.0.0.1にアクセスできません。Nodus の外部にある外部 HTTPS トンネルが必要になります。サーバーを公開する場合は、トークンを保護してください。",
  "Cliente genérico": "一般的なクライアント",
  "Transporte: Streamable HTTP. Endpoint: la URL anterior. Auth: la cabecera Authorization: Bearer <token>.": "トランスポート: ストリーミング可能な HTTP。エンドポイント: 上記の URL。認証: Authorization: Bearer <token> ヘッダー。",
  "Descargando el cliente oficial…": "公式クライアントをダウンロードしています…",
  "Comprobando permisos y conexión…": "権限と接続を確認しています…",
