  "Nodus eliminará de este equipo el ID del túnel y la clave de ejecución guardada. Podrás configurarlos otra vez cuando quieras.": "Nodus は、トンネル ID と保存されているランタイムキーをこのデバイスから削除します。いつでも再構成できます。",
