  "⚠ Sin un modelo seleccionado podrás sincronizar metadatos, pero no analizar temas ni ideas hasta configurarlo.": "⚠ モデルを選択しないとメタデータを同期できますが、テーマやアイデアを構成するまでは分析できません。",
