  "La sincronización puede funcionar, pero Nodus necesita un modelo predeterminado para extraer temas, ideas y evidencias.": "同期は機能しますが、Nodus にはテーマ、アイデア、証拠を抽出するためのデフォルトのモデルが必要です。",
  "Sincroniza Zotero para crear el corpus": "Zotero を同期してコーパスを作成する",
  "Todavía no hay obras locales. Revisa las colecciones monitorizadas y ejecuta una sincronización para poblar la biblioteca.": "ローカル作品はまだありません。監視対象のコレクションを確認し、同期を実行してライブラリにデータを追加します。",
