  "El grafo ya puede orientarte por temas; el siguiente salto de valor llega al analizar a fondo las obras leídas o seleccionadas.": "グラフはすでにテーマごとに方向性を示すことができます。価値の次の飛躍は、あなたが読んだ、または選択した作品を深く分析することによってもたらされます。",
  "Analizar ideas": "アイデアを分析する",
  "Indexa embeddings pendientes": "保留中の埋め込みのインデックス作成",
  "Hay ideas extraídas sin índice semántico. Indexarlas mejora la fusión, las relaciones y el descubrimiento de puentes.": "意味論的なインデックスを持たずに抽出されたアイデアがあります。それらにインデックスを付けると、融合、関係、ブリッジの発見が向上します。",
