  "Revisa huecos y contradicciones": "ギャップや矛盾を見直す",
  "El corpus ya tiene material interpretativo. El siguiente paso útil es convertir huecos y tensiones en una ruta de lectura o pregunta de investigación.": "コーパスには解釈資料が含まれています。次の有益なステップは、ギャップや緊張を読書の流れや研究課題に変えることです。",
