  "Encadena temas, ideas, resumen, indexado (ideas y pasajes) y descubrimiento de relaciones.": "テーマ、アイデア、要約、インデックス作成 (アイデアと文章)、および関係の発見をチェーン化します。",
  "Encadena temas, ideas, resumen, indexado (ideas y pasajes) y descubrimiento de relaciones para toda la biblioteca filtrada.": "フィルタリングされたライブラリ全体のテーマ、アイデア、要約、インデックス作成 (アイデアと文章)、および関係の発見をチェーンします。",
  "Procesar todo encadena para las {n} obra(s) filtrada(s): temas, ideas, resumen, indexado (ideas y pasajes) y descubrimiento de relaciones. Es una operación larga que consume tokens del modelo seleccionado. ¿Continuar?": "{n} でフィルタリングされた作品のすべてのチェーンを処理します: テーマ、アイデア、要約、インデックス付け (アイデアと文章)、関係の発見。これは、選択したモデルからのトークンを消費する長い操作です。続く？",
  "Procesado completo en cola para {n} obra(s). Verás el progreso en la cola.": "{n} 個の作業の完全な処理がキューに入れられました。キューの進行状況が表示されます。",
  "Después elige Temas, Ideas o Ambos.": "次に、テーマ、アイデア、またはその両方を選択します。",
