  "Reconstruye los temas padre de toda la biblioteca con análisis ligero. Útil tras cambiar criterios temáticos.": "ライト分析を使用してライブラリ全体の親テーマを再構築します。テーマの基準を変更した後に役立ちます。",
  "Reasignar": "再割り当て",
  "Genera embeddings para las ideas que aún no los tienen. No regenera los existentes.": "不足しているアイデアの埋め込みを生成します。既存のものは再生成しません。",
  "Borra todos los embeddings y los regenera desde cero. Útil tras cambiar de modelo de embeddings.": "すべての埋め込みを削除し、最初から再生成します。埋め込みモデルを変更した後に役立ちます。",
  "Descubrir relaciones": "関係性を発見する",
  "Usa embeddings e IA para validar puentes semánticos entre ideas que aún no están conectadas. El progreso se muestra en la cola.": "埋め込みと AI を使用して、まだ結びついていないアイデア間のセマンティックな橋渡しを検証します。進行状況がキューに表示されます。",
