  "Detecta obras repetidas (mismo DOI, o mismo título, año y autores) y te deja revisarlas y fusionarlas conservando una sola copia. La misma obra en varias colecciones de Zotero no se duplica.": "繰り返される作品 (同じ DOI、同じタイトル、年、著者) を検出し、それらをレビューして1つのコピーにマージできます。Zoteroの複数のコレクションにある同じ作品は複製されません。",
