  "Fusionar todos los duplicados": "すべての重複をマージする",
  "Se fusionarán {g} grupo(s), conservando en cada uno la copia marcada y reasignando sus ideas, evidencia y etiquetas. Las {n} copias sobrantes se eliminarán de la biblioteca de Nodus (Zotero no se modifica). ¿Continuar?": "これにより、{g} グループがマージされ、マークされたコピーがそれぞれに保持され、アイデア、証拠、タグが再指定されます。 {n} の余剰コピーは Nodus ライブラリから削除されます (Zotero は変更されていません)。続く？",
  "Duplicados": "重複",
  "Buscar y fusionar ideas duplicadas para limpiar el grafo y el listado": "重複するアイデアを見つけて結合し、グラフとリストをクリーンアップします。",
  "Ideas duplicadas": "重複したアイデア",
  "Buscando ideas duplicadas…": "重複するアイデアを探しています…",
  "No se han encontrado ideas duplicadas.": "重複するアイデアは見つかりませんでした。",
  "{g} grupo(s) · {n} idea(s) duplicadas a fusionar": "{g} 個のグループ · {n} 個の重複したアイデアをマージします",
  "Solo se agrupan ideas con la misma etiqueta y el mismo tipo. La evidencia se conserva íntegra al fusionar.": "同じラベルとタイプを持つアイデアのみがグループ化されます。証拠はマージ時に完全に保存されます。",
  "Misma etiqueta": "同じラベル",
  "Copia de seguridad creada antes de fusionar:": "マージ前に作成されたバックアップ:",
  "{n} evidencia(s)": "{n} の証拠",
  "Fusionar todas las ideas duplicadas": "重複したアイデアをすべてマージする",
  "Se hará primero una copia de seguridad completa de la base de datos. Después se fusionarán {g} grupo(s), conservando en cada uno la idea marcada y reasignándole toda la evidencia, ocurrencias, temas y conexiones del grafo de las {n} copias sobrantes, que se eliminarán. La evidencia no se pierde. ¿Continuar?": "最初にデータベースの完全バックアップが作成されます。次に、{g} 個のグループがマージされ、マークされたアイデアがそれぞれに保持され、{n} 個の余剰コピーからすべての証拠、出来事、テーマ、グラフの接続が再指定され、その後削除されます。証拠が失われることはありません。続く？",
  "Seleccionar los {n} resultados filtrados": "{n} でフィルタリングされた結果を選択します",
