  "Grafo de la obra": "作品のグラフ",
  "Grafo de ideas · {title}": "アイデアグラフ · {title}",
  "{n} idea(s) de esta obra · haz clic en un nodo para expandir sus conexiones": "この作品からの {n} 個のアイデア · ノードをクリックして接続を展開します",
