  "Esta obra aún no tiene ideas extraídas.": "この作品にはまだアイデアが抽出されていません。",
  "Ejecuta un análisis profundo de la obra para verla en el grafo.": "作業の詳細な分析を実行して、グラフで確認します。",
  "Ideas de la obra": "作品のアイデア",
