  "Analizar las {n} seleccionadas": "選択した {n} を分析します",
  "Analizar solo un paso": "単一ステップを分析する",
  "Preparar búsqueda semántica": "セマンティック検索の準備",
  "Indexar texto citable": "引用可能なテキストの索引付け",
  "Genera los embeddings que faltan para poder encontrar ideas por significado. No regenera los existentes.": "欠落している埋め込みを生成して、アイデアを意味から見つけられるようにします。既存のものは再生成されません。",
  "Preparar las que falten": "足りないものを用意する",
  "Indexa los fragmentos de texto completo que falten o estén obsoletos, en toda la biblioteca. No requiere análisis de ideas y los ya actuales se omiten.": "ライブラリ全体にわたって、欠落しているか古いフルテキストフラグメントのインデックスを作成します。アイデアの分析は必要なく、既存のアイデアはスキップされます。",
  "Indexar lo que falte": "欠けているものをインデックス化する",
  "Filtros avanzados": "高度なフィルター",
  "Combina condiciones sueltas de la tubería de análisis. Los presets de arriba cubren los casos habituales.": "分析パイプラインの個々の条件を組み合わせます。上記のプリセットは通常のケースをカバーしています。",
  "Ver el detalle paso a paso": "ステップバイステップの詳細を確認する",
  "Necesita el texto completo de la obra.": "作品の全文が必要です。",
  "El análisis solo pudo usar el abstract.": "分析には要約のみを使用できます。",
  "Disponible en la obra.": "作品上でご利用いただけます。",
  "{n} fragmentos indexados": "{n} インデックス付きフラグメント",
  "Enviando…": "送信中…",
  "Faltan {n} paso(s). Se encolarán y verás el progreso en la cola.": "{n} ステップがありません。それらはキューに入れられ、キュー内の進行状況が表示されます。",
  "No queda nada pendiente en esta obra.": "この作業に関しては何も保留されていません。",
  "Reintentar lo que falta": "不足しているものを再試行してください",
  "Encola solo los pasos incompletos, pendientes o fallidos de cada obra seleccionada. No vuelve a analizar lo que ya está hecho.": "選択した各作業の不完全なステップ、保留中のステップ、または失敗したステップのみをキューに入れます。すでに行われたことを再度分析することはありません。",
  "No queda nada pendiente en la selección.": "選択中は何も保留されていません。",
  "Pendientes en cola para {n} obra(s). Verás el progreso en la cola.": "{n} 個の作業のためにキューに入れられた保留中のステップ。キューの進行状況が表示されます。",
  "Eliminar las {n} obras seleccionadas": "選択した{n}個の作品を削除します",
  "Se eliminarán del vault actual las {n} obra(s) seleccionada(s), junto con sus ideas extraídas, sus pasajes, sus embeddings y el resto de datos derivados. Las ideas y demás datos que compartan con otras obras se conservan. Esta acción no se puede deshacer.": "{n} 個の選択された作品は、抽出されたアイデア、パッセージ、埋め込み、および残りの派生データとともに、現在のVaultから削除されます。他の作品と共有されたアイデアやその他のデータは保持されます。これを元に戻すことはできません。",
  "Elimina estas obras del vault actual con sus ideas, pasajes, embeddings y demás datos derivados. Lo que otras obras comparten no se toca.": "これらの作品を、アイデア、一節、埋め込み、その他の派生データとともに現在のVaultから削除します。他の作品が共有しているものはそのまま残されます。",
  "No se pueden eliminar obras que se están analizando ahora mismo ({n}). Espera a que terminen o detén la cola.": "現在解析中の作品は削除できません({n})。完了するまで待つか、キューを停止します。",
  "Se eliminaron {n} obra(s) del vault.": "{n} 個の作品がVaultから削除されました。",
  "No se pudieron eliminar las obras seleccionadas.": "選択した作品を削除できませんでした。",
  "No aplica": "適用できない",
  "Solo abstract": "抄録のみ",
  "Nodus no encontró texto que leer. Añade el PDF o EPUB en Zotero y vuelve a analizar.": "ノダスは読むべきテキストを見つけられませんでした。 Zotero に PDF または EPUB を追加して、再度分析します。",
  "Zotero no está disponible. Ábrelo y vuelve a analizar.": "Zoteroは利用できません。それを開いて再度分析します。",
  "El análisis solo pudo usar el abstract, así que esta obra no tendrá texto citable. Añade el PDF o EPUB en Zotero y vuelve a analizar.": "分析では要約のみを使用できるため、この作品には引用可能なテキストがありません。 Zotero に PDF または EPUB を追加して、再度分析します。",
  "Ver las {n} ideas de esta obra": "この作品の{n}アイデアを見る",
  "Analizar: temas, ideas, resumen, indexado y relaciones": "分析: テーマ、アイデア、要約、インデックス付け、関係",
