  "Incompleto": "不完全",
  "Búsqueda semántica": "セマンティック検索",
  "Texto citable": "引用可能なテキスト",
  "Pulsa «Analizar» en la fila de una obra, o selecciona varias y analízalas juntas. Nodus lee el texto, extrae temas padre, ideas con evidencia y relaciones, y las añade al grafo. La columna Estado te dice en qué punto va cada obra.": "作品の行で«分析»を押すか、複数を選択して一緒に分析します。 Nodus はテキストを読み、親テーマ、証拠と関係のあるアイデアを抽出し、それらをグラフに追加します。 [ステータス] 列には、各作業がどの程度進んでいるのかが表示されます。",
  "Procesar todo: temas, ideas, resumen, indexado y relaciones": "テーマ、アイデア、要約、インデックス付け、関係などすべてを処理します。",
