  "Ver esta idea conectada": "このつながりのあるアイデアをご覧ください",
  "No se pudo cargar el detalle de la idea.": "アイデアの詳細を読み込めませんでした。",
  "Lectura:": "読む：",
  "Preguntar al asistente sobre esta obra": "この作品についてアシスタントに聞く",
  "Analiza esta lectura dentro del corpus: ideas extraídas, temas, huecos, contradicciones y próximas lecturas relacionadas.": "コーパス内のこの読みを分析します。抽出されたアイデア、テーマ、ギャップ、矛盾、および関連する次の読みです。",
  "Reasignar temas vuelve a ejecutar el análisis ligero (título + abstract) sobre TODA la biblioteca para reconstruir los temas padre y agrupar las ideas existentes bajo ellos. Consume tokens del modelo seleccionado. ¿Continuar?": "テーマを再割り当てすると、ライブラリ全体に対してライト分析 (タイトル + 要約) が再実行され、親テーマが再構築され、その下に既存のアイデアがグループ化されます。選択したモデルからのトークンを消費します。続く？",
  "Reasignación de temas en cola para {n} obra(s). Verás el progreso en la cola.": "テーマの再割り当ては {n} 個の作品に対してキューに入れられています。キューの進行状況が表示されます。",
