  "Analiza esta contradicción del corpus. Resume las posiciones, evidencia y lecturas necesarias para decidir si es tensión real o diferencia de marco.": "コーパス内のこの矛盾を分析します。それが本当の緊張なのか、それとも枠組みの違いなのかを判断するために必要な立場、証拠、読みどころをまとめます。",
