  "Temas principales": "主なテーマ",
  "Los temas principales son los grandes nodos que agrupan tus ideas en el grafo. Añade los tuyos para controlarlos manualmente; mientras estén bloqueados, los análisis solo usarán estos temas y no generarán otros nuevos.": "主要なテーマは、グラフ内のアイデアをグループ化する大きなノードです。独自のものを追加して手動で制御します。ロックされている間、分析ではこれらのテーマのみが使用され、新しいテーマは生成されません。",
