  "Las imágenes no contienen una capa textual. Usa el Markdown limpio para buscar el OCR.": "画像にはテキストレイヤーがありません。クリーンな Markdown を使用して OCR テキストを検索します。",
  "Coincidencia {current} de {total}": "{total} の {current} と一致します",
