  "Limpiar fallidos": "クリア失敗",
  "pág.": "pp.",
  "Pedido desde un cliente MCP": "MCPクライアントからのリクエスト",
  "Quitar de la cola": "キューから削除",
  "No se pudo quitar el informe de la cola.": "レポートをキューから削除できませんでした。",
  "Falló": "失敗した",
  "Abrir a pantalla completa": "全画面で開く",
  "Lectura a pantalla completa": "全画面表示",
  "Salir de pantalla completa": "全画面表示のままにする",
  "Leer": "読む",
  "Reutilizar la idea para un informe nuevo": "新しいレポートのアイデアを再利用する",
  "Volver a la galería": "ギャラリーに戻る",
  "El informe desarrolla tu idea por completo, citando todo el corpus.": "レポートは、コーパス全体を引用して、あなたのアイデアを完全に展開します。",
  "Se añadirá a la cola ({n} en curso) y se generará cuando termine el anterior.": "これはキューに追加され ({n} が進行中)、前のキューが終了すると生成されます。",
  "Se genera en segundo plano: puedes cerrar esto y seguir trabajando.": "バックグラウンドで生成されます。これを閉じて作業を続けることができます。",
  "Añadir a la cola": "キューに追加",
  "Informe añadido a la cola. Se generará en segundo plano.": "レポートがキューに追加されました。バックグラウンドで生成されます。",
  "Pulsa «Nuevo informe» y escribe la pregunta o idea. El informe la convierte en un texto de varias páginas, no en una respuesta corta.": "「新規レポート」を押して質問やアイデアを書き込んでください。このレポートは、短い回答ではなく、複数ページのテキストに変換します。",
  "2. Encola los que quieras": "2. 好きなだけキューに入れます",
  "Añade varios informes a la cola: se generan en cadena, uno tras otro, mientras sigues trabajando.": "いくつかのレポートをキューに追加します。作業を続けている間、レポートは次々に生成されます。",
  "4. Lee a pantalla completa": "4.全画面で読む",
  "Abre cualquier informe de la galería para leerlo a pantalla completa, revisar sus citas y exportarlo a Markdown o PDF.": "ギャラリー内のレポートを開いて全画面で読み、引用を確認し、Markdown または PDF にエクスポートします。",
  "Taller": "ワークショップ",
  "Informe guardado localmente.": "レポートはローカルに保存されました。",
  "Informe guardado abierto. Puedes exportarlo o reutilizar su idea para regenerarlo.": "保存されたレポートが開きました。エクスポートしたり、そのアイデアを再利用して再生成したりできます。",
  "Idea reutilizada: ajusta los parámetros y genera un informe actualizado.": "アイデアの再利用: パラメーターを調整し、更新されたレポートを生成します。",
  "¿Eliminar este informe guardado? Esta acción no se puede deshacer.": "この保存されたレポートを削除しますか?この操作は元に戻すことができません。",
  "Informe eliminado.": "レポートが削除されました。",
  "1. Plantea la idea": "1. アイデアを組み立てる",
  "Escribe la pregunta o idea de investigación que quieres desarrollar. El informe la convierte en un texto de varias páginas, no en una respuesta corta.": "研究の疑問や開発したいアイデアを書きます。このレポートは、短い回答ではなく、複数ページのテキストに変換します。",
  "2. Ajusta el alcance": "2. スコープを設定する",
  "Elige la extensión objetivo y el número máximo de secciones. Menos secciones producen un texto más profundo; más secciones, uno más panorámico.": "ターゲットの長さとセクションの最大数を選択します。セクションが少ないほど、より深いテキストが作成されます。より多くのセクション、よりパノラマなセクション。",
  "3. Cobertura del corpus": "3. コーパスの範囲",
  "Nodus recorre todo el corpus indexado, planifica las secciones y redacta guiado por la cobertura, citando cada obra sin que tengas que seleccionarla.": "Nodus はインデックス付きコーパス全体を調べ、セクションを計画し、カバレッジに基づいて執筆し、ユーザーが選択することなくすべての作品を引用します。",
  "4. Revisa y exporta": "4. レビューとエクスポート",
  "Abre las citas para comprobar cada fuente, guarda el informe para retomarlo y expórtalo a Markdown o PDF cuando esté listo.": "引用を開いて各ソースを確認し、レポートを保存して後で再開し、準備ができたら Markdown または PDF にエクスポートします。",
  "Informe académico de varias páginas, guiado por cobertura y con todas las fuentes citadas.": "複数ページにわたる学術レポート。取材範囲に基づいてガイドされ、すべての情報源が引用されています。",
  "Adaptativo (según corpus)": "アダプティブ (コーパスから)",
  "Conciso (5–8 pág.)": "簡潔 (5 ～ 8ページ)",
  "Estándar (9–14 pág.)": "標準 (9 ～ 14ページ)",
  "Exhaustivo (15–20 pág.)": "網羅的 (15 ～ 20ページ)",
  "Extensión objetivo del informe": "目標レポートの長さ",
  "Extensión:": "長さ：",
  "Secciones:": "セクション:",
  "Número máximo de secciones (menos secciones = mayor profundidad)": "セクションの最大数 (セクションが少ないほど深さが増します)",
  "Secciones: Auto (IA decide)": "セクション：自動（AIが判断）",
  "Bloque único · sin secciones": "単一の連続ブロック・セクションなし",
  "Estructura del informe": "レポートの構造",
  "Una narración continua sin encabezados internos; conserva toda la recuperación y el análisis.": "内部見出しのない1つの連続した物語。すべての検索と分析は保存されます。",
  "El esquema manual fija exactamente las partes y su orden.": "マニュアルのアウトラインでは、正確な部分とその順序が修正されています。",
  "La estructura organiza el informe, pero nunca limita la evidencia relevante.": "構造はレポートを整理しますが、関連する証拠を制限することはありません。",
  "Secciones: Auto": "セクション: 自動",
  "Máx. {n} secciones": "最大 {n} セクション",
  "Máx. 4 secciones": "最大4セクション",
