  "Vincular a proyecto (opcional)": "プロジェクトへのリンク (オプション)",
  "Sin proyecto": "プロジェクトがありません",
  "Generar informe": "レポートの生成",
  "Generando informe…": "レポートを生成中…",
  "No se pudo generar el informe.": "レポートを生成できませんでした。",
  "Escribe la idea de investigación antes de generar el informe.": "レポートを作成する前に、研究アイデアを書き留めます。",
  "Escribe la idea o pregunta de investigación. El informe la desarrollará por completo, citando todas las obras del corpus.": "研究のアイデアや質問を書きます。このレポートでは、コーパス内のすべての成果を引用しながら、それを完全に発展させます。",
  "Cobertura del corpus completo": "コーパス全体を網羅",
  "Sin selección manual: el informe elige y cita las fuentes por ti.": "手動で選択する必要はありません。レポートはソースを選択して引用します。",
  "Puedes cambiar de sección: el informe seguirá en segundo plano y recuperarás este progreso al volver.": "セクションを切り替えることができます。レポートはバックグラウンドで続行され、戻ったときにこの進行状況が返されます。",
  "Informe generado: {s} secciones · ~{p} páginas · {i} ideas citadas.": "生成されたレポート: {s} セクション · ~{p} ページ · {i} 個のアイデアが引用されました。",
  "Informe generado y guardado: {s} secciones · ~{p} páginas · {i} ideas citadas.": "生成および保存されたレポート: {s} セクション · ~{p} ページ · {i} 個のアイデアが引用されました。",
  "Informe generado, pero no se pudo guardar automáticamente: {error}": "レポートは生成されましたが、自動的に保存できませんでした: {error}",
  "El informe está listo y puedes guardarlo manualmente.": "レポートの準備が完了したので、手動で保存できます。",
  "El informe aparecerá aquí. Escribe tu idea de investigación y pulsa «Generar informe».": "レポートはここに表示されます。研究アイデアを書いて「レポートを作成」を押してください。",
  "Planifica, redacta sección a sección guiado por la cobertura del corpus y ensambla un informe académico de 5–20 páginas con todas las fuentes citadas.": "計画を立て、コーパスの範囲に基づいてセクションごとに執筆し、すべての情報源を引用した5 ～ 20ページの学術レポートを作成します。",
