  "1. Delimita": "1. 定義する",
  "Escribe el apartado que quieres construir: pregunta, capítulo, debate, hueco o marco teórico. Cuanto más concreto sea el objetivo, mejor se ordena la mesa.": "質問、章、議論、ギャップ、または理論的枠組みなど、構築したいセクションを書きます。目的が具体的であればあるほど、表はより適切に整理されます。",
  "2. Monta la mesa": "2. テーブルをセットする",
  "Pulsa Preparar mesa y revisa ideas, temas, huecos, contradicciones, obras y rutas. Usa Todas las ideas cuando quieras una revisión amplia del corpus encontrado.": "[テーブルの準備] をクリックして、アイデア、テーマ、ギャップ、矛盾、作品、ルートを確認します。見つかったコーパスを幅広くレビューしたい場合は、「すべてのアイデア」を使用します。",
  "3. Decide el foco": "3. 焦点を決める",
  "Selecciona todo para explorar, vacía para empezar de cero o ajusta cada pestaña. La matriz final te dirá qué papel cumple cada material en el argumento.": "探索するすべてを選択するか、クリアして最初から開始するか、各タブを調整します。最後のマトリックスは、各マテリアルが議論の中でどのような役割を果たしているかを示します。",
  "4. Convierte en texto": "4. テキスト化",
  "Genera el borrador, abre las citas para verificar fuentes, guárdalo si quieres retomarlo y exporta Markdown cuando el hilo argumental ya tenga sentido para tu manuscrito.": "下書きを生成し、引用を開いて出典を確認し、元に戻りたい場合は保存し、議論のスレッドが原稿にとって意味のあるものになったら Markdown をエクスポートします。",
