  "La búsqueda por significado necesita embeddings. Configura el proveedor y la clave de embeddings en Ajustes e indexa la biblioteca.": "セマンティック検索には埋め込みが必要です。 [設定] で埋め込みプロバイダーとキーを構成し、ライブラリにインデックスを付けます。",
  "Salud del corpus": "体の健康",
  "Qué falta por analizar, indexar o recuperar.": "分析、インデックス付け、または回復が必要な部分。",
  "Sin texto": "テキストなし",
  "Solo análisis ligero": "光分析のみ",
  "Prioritarias por analizar": "分析の優先順位",
  "Recuperar texto": "テキストを回復する",
  "ideas pend.": "保留中のアイデア",
  "{n} obras con pasajes pendientes": "未処理のパッセージがある作品 {n} 件",
  "Próximas acciones": "次のアクション",
  "Todo en orden: no hay análisis, indexado ni recuperación pendientes.": "すべてクリア: 保留中の分析、インデックス作成、またはリカバリはありません。",
  "Analiza a fondo {n} obra(s) prioritaria(s)": "{n} 個の優先作業を詳細に分析します",
  "Marcadas como leídas o seleccionadas, pero todavía sin ideas extraídas.": "既読または選択済みとしてフラグが立てられていますが、アイデアはまだ抽出されていません。",
  "Profundiza {n} obra(s) con solo análisis ligero": "ライト分析のみで {n} の作業を深めます",
  "Tienen temas pero aún no ideas; son las candidatas naturales al análisis profundo.": "テーマはあるものの、アイデアはまだありません。詳細な分析の自然な候補。",
  "Indexa {n} idea(s) sin embedding": "{n} 個のアイデアを埋め込みなしでインデックス付けします",
  "La búsqueda por significado, la fusión y los puentes dependen del índice semántico.": "セマンティック検索、融合、ブリッジはすべてセマンティックインデックスに依存します。",
  "Indexa pasajes de {n} obra(s) con texto": "{n} 作品の文章にテキストを索引付けします",
  "Sin pasajes no hay búsqueda semántica de evidencia ni citas a nivel de fragmento.": "パッセージがなければ、意味論的な証拠の検索や断片レベルの引用はできません。",
  "Recupera el texto de {n} obra(s)": "{n} 個の作品のテキストを回復します",
  "No se pudo extraer texto, pero hay vía de recuperación (re-escanear, OCR o descargar por DOI).": "テキストを抽出できませんでしたが、回復パス (再スキャン、OCR、または DOI によるフェッチ) があります。",
  "Flujo guiado de tesis": "ガイド付き論文の流れ",
  "Flujo guiado de artículo": "ガイド付き記事の流れ",
  "Flujo guiado de manuscrito": "ガイド付き原稿フロー",
  "Proyecto listo para revisar, exportar o cerrar.": "プロジェクトをレビュー、エクスポート、または閉じる準備ができています。",
  "Brief y pregunta": "概要と質問",
  "Objetivo, alcance y criterio de lectura definidos.": "目的、範囲、読み取り基準が定義されています。",
  "Pregunta y cobertura": "質問と取材内容",
  "Pregunta principal conectada con la cobertura del corpus.": "コーパスの範囲に関連する主な質問。",
  "Corpus y materiales": "コーパスと資料",
  "Obras, ideas, notas, huecos o borradores listos para integrarse.": "すぐに統合できる作品、アイデア、メモ、ギャップ、または下書き。",
  "Estructura argumental": "引数の構造",
  "Debates, huecos y borradores organizados antes de intervenir el texto.": "テキストを編集する前に、議論、ギャップ、下書きを整理します。",
  "Manuscrito": "原稿",
  "Capítulo o artículo importado como texto editable y versionado.": "章または記事は、編集可能でバージョン管理されたテキストとしてインポートされます。",
  "Revisión y salida": "レビューと出力",
  "Relaciones, sugerencias verificables y exportación final.": "関係、検証可能な提案、および最終的なエクスポート。",
  "Editar brief": "概要を編集する",
  "Marcar cobertura": "マークカバレッジ",
  "Preparar materiales": "材料を準備する",
  "Preparar estructura": "構造を準備する",
  "Subir capítulo": "章をアップロードする",
  "Revisar capítulo": "レビューの章",
  "Completado": "完了",
  "Objetivo, alcance, pregunta principal y criterio de selección": "目的、範囲、主な質問、選択基準",
  "Guardar brief": "概要を保存",
  "Brief actualizado. El flujo guiado ya usa este objetivo.": "概要を更新しました。ガイド付きフローはこの目的を使用するようになりました。",
  "Cobertura marcada como en curso.": "カバレッジは進行中としてマークされています。",
  "Materiales preparados para el estado de la cuestión.": "文献レビュー用に準備された資料。",
  "Estructura argumental preparada.": "引数構造が準備されました。",
  "No se encontraron nuevas sugerencias verificables para este capítulo.": "この章に関する新しい検証可能な提案は見つかりませんでした。",
  "Define el objetivo, el alcance, la pregunta principal y el criterio de selección de fuentes. Este texto aparece en la cabecera del proyecto, se envía como contexto a la IA al generar sugerencias y se incluye en la exportación.": "目的、範囲、主な質問、およびソースの選択基準を定義します。このテキストはプロジェクトヘッダーに表示され、提案の生成時にコンテキストとして AI に送信され、エクスポートに含まれます。",
  "Vincula tu pregunta de investigación con el corpus: indica qué áreas ya están cubiertas y qué falta por explorar. Marcar este paso como en curso activa la sección de cobertura en el proyecto.": "研究の質問をコーパスに関連付けます。どの領域がすでにカバーされており、どの領域がまだ調査されていないのかを示します。このステップを進行中としてマークすると、プロジェクト内のカバレッジセクションがアクティブになります。",
  "Añade obras, ideas, notas, huecos, debates y borradores al proyecto. Estos materiales son los que la IA usará para proponer inserciones con citas verificables en el manuscrito.": "作品、アイデア、メモ、ギャップ、議論、下書きをプロジェクトに追加します。これらの資料は、AI が原稿内に検証可能な引用を含む挿入を提案するために使用します。",
  "Organiza los debates, huecos y borradores que estructurarán el argumento antes de redactar los capítulos. Puedes activar cada bloque por separado para marcar que está listo para usarse.": "各章の草案を作成する前に、議論を構成するための議論、ギャップ、草案を整理します。各ブロックを個別にアクティブにして、使用可能としてマークすることができます。",
  "Importa un capítulo o artículo como texto editable. Nodus lo versiona automáticamente y permite aplicar sugerencias sobre el borrador.": "章または記事を編集可能なテキストとしてインポートします。 Nodus は自動的にバージョンを作成し、提案をドラフトに適用できるようにします。",
  "Genera sugerencias verificables contra el corpus y revisa las citas del manuscrito antes de exportar o cerrar el proyecto.": "プロジェクトをエクスポートまたは終了する前に、コーパスに対して検証可能な提案を生成し、原稿の引用をレビューします。",
