  "Sube un capítulo o artículo para convertirlo en texto editable. Se guardará como nota vinculada y versionada.": "章または記事をアップロードして、編集可能なテキストにします。これは、リンクされたバージョン付きのメモとして保存されます。",
  "Genera sugerencias de inserción con citas verificables y revisa las citas del capítulo antes de exportar.": "検証可能な引用を含む挿入候補を生成し、エクスポートする前に章の引用を確認します。",
  "Sección actualizada. El flujo guiado refleja el cambio.": "セクションが更新されました。ガイド付きフローは変更を反映します。",
  "Relaciones": "関係",
  "Analizar relaciones": "関係を分析する",
  "{n} ideas del capítulo": "{n} 章のアイデア",
  "Extrae las ideas de este capítulo (no se añaden al grafo) y busca cómo se relacionan con tu biblioteca: ideas, notas, pasajes y obras.": "この章のアイデアを抽出し (グラフには追加されません)、アイデア、メモ、文章、作品など、ライブラリとの関連性を確認します。",
  "Analiza las relaciones para ver cómo conecta este capítulo con toda tu biblioteca.": "関係を分析して、この章がライブラリ全体とどのように関連しているかを確認します。",
  "Sin relaciones encontradas en la biblioteca.": "ライブラリに関係が見つかりませんでした。",
  "La búsqueda de relaciones necesita un proveedor de embeddings configurado en Ajustes.": "関係を見つけるには、設定で構成された埋め込みプロバイダーが必要です。",
  "No se pudieron extraer ideas de este capítulo.": "この章からはアイデアを引き出すことができませんでした。",
  "Analizadas {n} idea(s) del capítulo y sus relaciones con la biblioteca.": "{n} 章のアイデアとライブラリとの関係を分析しました。",
