  "Detecta afirmaciones del capítulo, comprueba si ya tienen cita y solo marca las que coinciden con ideas o pasajes del corpus.": "章の主張を検出し、すでに引用があるかどうかを確認し、一致するコーパスのアイデアや文章にのみフラグを立てます。",
