  "Cita aplicada al borrador sobre una versión nueva recuperable.": "引用は新しい回復可能なバージョンのドラフトに適用されます。",
  "No se pudo localizar la frase exacta en el borrador; insértala manualmente desde el texto.": "草案には正確な文が見つかりませんでした。テキストから手動で挿入します。",
  "Eliminar proyecto": "プロジェクトの削除",
  "Proyecto eliminado.": "プロジェクトが削除されました。",
  "¿Eliminar el proyecto «{title}»? Se borrarán sus secciones, vínculos y capítulos. Las notas y carpetas creadas se conservan. Esta acción no se puede deshacer.": "プロジェクト「{title}」を削除しますか?そのセクション、リンク、章は削除されます。作成したメモやフォルダーは保存されます。この操作は元に戻すことができません。",
