  "Auditoría": "監査",
  "Auditoría de relaciones": "関係監査台帳",
  "Ver y deshacer tus veredictos sobre relaciones (confirmadas y rechazadas)": "関係の判定 (確認または拒否) を確認して取り消します。",
  "Aún no has auditado ninguna relación. Abre una arista en el grafo y usa «Confirmar» o «Marcar como incorrecta».": "まだ関係を監査していません。グラフのエッジを開いて、「確認」または「不正確としてマーク」を使用します。",
  "Rechazadas (ocultas del grafo y de los análisis)": "拒否 (グラフと分析から非表示)",
  "Confirmadas por ti": "あなたによって確認されました",
