  "Has marcado esta relación como incorrecta: desaparecerá del grafo y de los análisis.": "この関係は間違っているとマークされました。この関係はグラフと分析から消えます。",
  "Marcar esta relación como verificada por ti": "この関係をあなたが検証済みとしてマークします",
