  "Copias de seguridad automáticas": "自動バックアップ",
  "Copias cifradas periódicas en una carpeta a tu elección. Cada copia incluye todo Nodus; puedes usar iCloud Drive, Google Drive o Dropbox para mantenerla fuera de este equipo.": "選択したフォルダーに定期的に暗号化されたコピーが保存されます。すべてのバックアップには Nodus のすべてが含まれます。 iCloud Drive、Google Drive、または Dropbox を使用して、このマシンにアクセスしないようにしてください。",
  "Cada copia protege todo Nodus automáticamente.": "すべてのバックアップにより、Nodus がすべて自動的に保護されます。",
  "Incluye todas las bóvedas, documentos, preferencias, historiales, archivos generados y claves API. No existen exclusiones configurables.": "これには、すべてのVault、ドキュメント、設定、履歴、生成されたファイル、および API キーが含まれます。構成可能な除外はありません。",
  "Elegir carpeta": "フォルダーを選択してください",
  "Sin carpeta elegida": "フォルダが選択されていません",
  "Cada 12 horas": "12時間ごと",
  "Cada día": "毎日",
  "Cada semana": "毎週",
  "Contraseña maestra configurada (guardada en el llavero del sistema).": "マスターパスワードセット (システムキーチェーンに保存)。",
  "Contraseña maestra y clave de recuperación configuradas.": "マスターパスワードと回復キーが設定されています。",
  "Guardar kit de recuperación": "リカバリーキットを保存する",
  "Cambiar contraseña": "パスワードを変更する",
  "Contraseña maestra eliminada. Las copias automáticas quedan en pausa.": "マスターパスワードが削除されました。自動バックアップは一時停止されます。",
  "Contraseña maestra (mín. 8 caracteres)": "マスターパスワード (8文字以上)",
  "Guardar contraseña": "パスワードを保存する",
  "Contraseña maestra guardada. Descarga el kit de recuperación: sin la contraseña, las copias no se pueden restaurar.": "マスターパスワードが保存されました。リカバリキットをダウンロードします。パスワードがないとバックアップを復元できません。",
  "Contraseña maestra guardada. Descarga el kit: permite recuperar incluso si olvidas la contraseña.": "マスターパスワードが保存されました。キットをダウンロードすると、パスワードを忘れた場合でも回復できます。",
  "Credenciales de recuperación de la copia": "バックアップ・リカバリ認証情報",
  "Guarda ambas fuera de este dispositivo. Podrás importar la copia con cualquiera de ellas.": "どちらも本装置から離れた場所に保管してください。どちらでもバックアップをインポートできます。",
  "Contraseña": "パスワード",
  "Clave de recuperación": "回復キー",
  "Copiadas": "コピーされました",
  "Copiar credenciales": "認証情報をコピーする",
  "Introduce la contraseña o la clave de recuperación. Después selecciona el archivo .nodus.": "パスワードまたは回復キーを入力し、.nodus ファイルを選択します。",
  "Mostrar contraseña": "パスワードを表示",
