  "Lleva tus notas, borradores, búsquedas guardadas, auditorías de relaciones y bases de datos a otro equipo. Al importar se fusiona: gana la versión más reciente y nunca se borra nada local.": "メモ、下書き、保存された検索、関係監査、データベースを別のマシンに移動します。マージのインポート: 最新バージョンが優先され、ローカルのものは何も削除されません。",
