  "Carga un corpus de demostración de seis obras sobre la ciencia del aprendizaje. Podrás recorrer el grafo, ideas, debates, huecos y notas sin conectar Zotero ni configurar una clave de IA.": "学習科学に関する6つの作品からなるデモコーパスをロードします。 Zotero に接続したり、AI キーを設定したりせずに、グラフ、アイデア、議論、ギャップ、メモを探索できます。",
