  "Crea resúmenes de orientación independientes a partir de ideas, evidencia, temas y abstract. No son evidencia citable.": "アイデア、証拠、テーマ、要約から独立したオリエンテーションの概要を作成します。それらは引用可能な証拠ではありません。",
  "El análisis profundo solo usó el abstract, no el texto completo (el PDF/EPUB no estaba disponible al analizar). Reanaliza cuando esté en Zotero.": "詳細な分析では、全文ではなく要約のみが使用されました (分析時には PDF/EPUB は利用できませんでした)。 Zotero に入ったら再分析します。",
  "El texto o el modelo de embeddings cambió.": "テキストまたは埋め込みモデルが変更されました。",
  "Las ideas pertenecen a la versión anterior del texto. Vuelve a analizarlas para usar el texto actual.": "アイデアは以前のテキストバージョンに属します。現在のテキストを使用するには、それらを再度分析します。",
  "El texto cambió; vuelve a indexar sus fragmentos.": "テキストが変更されました。そのパッセージのインデックスを再度作成します。",
