  "Algunos fragmentos no tienen un embedding válido.": "一部のパッセージには有効な埋め込みがありません。",
  "Generar resúmenes faltantes": "欠落している概要を生成する",
  "Indexa fragmentos de texto completo en las obras que faltan o están obsoletas. No requiere análisis de ideas; el texto se mantiene como evidencia citable.": "不足している、または古い作品の全文断片にインデックスを付けます。アイデア分析は必要ありません。テキストは引用可能な証拠として残ります。",
