  "Reanálisis en cola para {n} obra(s) «solo abstract». Verás el progreso en la cola.": "{n} «abstract-only» 作品の再分析がキューに入れられました。キューの進行状況が表示されます。",
  "Reanaliza las obras que solo se analizaron con el abstract (el PDF/EPUB no estaba disponible al analizarlas). Las que ya tengan el texto disponible en Zotero recuperarán el análisis completo; el resto se omiten sin coste. ¿Continuar?": "抄録のみで分析された作品を再分析します（分析時には PDF/EPUB は利用できませんでした）。 Zotero でテキストを利用できるようになった人は、完全な分析を復元できるようになります。残りは無料でスキップされます。続く？",
  "Reanalizar": "再分析",
  "Reanalizar «solo abstract»": "«抄録のみ» を再分析する",
  "Recorre toda la biblioteca y actualiza solo los índices que hayan cambiado. Los ya actuales se omiten.": "ライブラリ全体をスイープし、変更されたインデックスのみを更新します。すでに最新のものはスキップされます。",
  "resumen": "まとめ",
  "solo abstract": "抽象のみ",
  "Vuelve a analizar las obras cuyo análisis profundo solo usó el abstract porque el PDF/EPUB no estaba disponible. Las que ya tengan el texto recuperan el análisis completo; el resto se omiten sin coste.": "PDF/EPUBが利用できなかったため、要約のみを使用して詳細な分析を行った作品を再分析します。現在テキストを持っている人は完全な分析を復元します。残りは無料でスキップされます。",
