  "Seccion del proyecto": "プロジェクトセクション",
  "texto completo": "全文",
  "Reinicializar el grafo": "グラフをリセットする",
  "Reinicializar el grafo borrará TODAS las ideas, temas, conexiones, autores y huecos, y dejará cada obra sin analizar. Tu biblioteca de Zotero y tus ajustes se conservan. Esta acción no se puede deshacer.": "グラフをリセットすると、すべてのアイデア、テーマ、つながり、作成者、ギャップが削除され、すべての作品が分析されないままになります。 Zotero ライブラリと設定は保持されます。この操作は元に戻すことができません。",
  "Eliminar borrador": "下書きの削除",
  "Eliminar informe": "レポートの削除",
  "Procesar toda la biblioteca": "ライブラリ全体を処理する",
