  "Por qué importa": "なぜそれが重要なのか",
  "La lección": "レッスン",
  "Lectura guiada: citas que un experto conoce de memoria": "ガイド付き読書: 専門家が暗記している引用",
  "Cómo leer este pasaje": "この一節の読み方",
  "Para retener": "保持するには",
  "Lectura guiada": "ガイド付き読書",
  "← → · progreso guardado": "← → · 進行状況が保存されました",
  "Voces de esta estación": "このステーションの声",
  "Obras sobre la mesa": "テーブル上での作業",
  "Esta inmersión": "このイマージョン",
  "estaciones": "ステーション",
  "citas": "引用",
  "preguntas": "質問",
  "El territorio completo": "領土全体",
  "Falta la clave del proveedor de IA: configúrala en Ajustes": "AI プロバイダーキーがありません。設定で設定してください",
  "Profundiza: informe Deep Research del tema": "さらに詳しく: トピックに関するDeep Researchレポート",
  "Ahora que dominas el tema, genera el informe académico de varias páginas con todas las fuentes citadas. Se guarda en Deep Research y podrás exportarlo o citarlo en tu escritura.": "トピックをマスターしたら、すべての情報源を引用した複数ページの学術レポートを作成します。これは Deep Research に保存されるため、エクスポートしたり、文章で引用したりできます。",
  "Puedes cambiar de sección: el informe seguirá generándose y mostrará el progreso al volver.": "セクションを切り替えることができます。レポートは生成を続け、戻ったときに進行状況を表示します。",
  "Dossier guardado: «{t}» · {s} secciones · ~{p} páginas. Lo tienes en Deep Research → informes guardados.": "保存されたドシエ: 「{t}」 · {s} セクション · ~{p} ページ。 Deep Research → 保存されたレポートで見つけてください。",
  "Generar de nuevo": "再度生成する",
  "Seleccionar modelo": "モデルを選択してください",
  "Usar modelo de síntesis": "合成モデルを使用する",
  "Modelo inicial para las tareas de IA ({n} disponibles)": "AI タスクの初期モデル ({n} が利用可能)",
  "Modelos favoritos para los selectores independientes": "独立セレクターのお気に入りモデル",
  "Los modelos de análisis se configuran en Ajustes.": "分析モデルは設定で構成されます。",
  "Modelos de análisis: Ajustes": "解析モデル：設定",
  "coge las ideas ya extraídas (afirmaciones, hallazgos…) y las vuelve a agrupar bajo estos temas con los modelos configurados en Ajustes, sin volver a leer los documentos ni re-extraer ideas.": "文書を読み直したりアイデアを再抽出したりすることなく、既に抽出されたアイデア (主張、調査結果など) を取得し、設定で構成されたモデルを使用してこれらのテーマの下に再グループ化します。",
  "Cada tarea usa su propio modelo. Los escaneos, resúmenes, fusión y embeddings obedecen estos ajustes; Chat, Deep Research, Inmersión y las demás herramientas conservan el modelo elegido dentro de su propia sección.": "各タスクは独自のモデルを使用します。スキャン、サマリー、フュージョン、埋め込みは次の設定に従います。チャット、Deep Research、イマージョン、その他のツールは、選択したモデルを独自のセクション内に保持します。",
  "Modelo de síntesis general (fallback inicial para herramientas con selector propio)": "一般的な合成モデル (独自のセレクターを持つツールの初期フォールバック)",
  "modelos por tarea": "タスク別のモデル",
  "Extracción: {provider}": "抽出: {provider}",
  "Síntesis: {provider}": "合成: {provider}",
  "Configura los modelos de IA": "AI モデルを構成する",
  "La sincronización puede funcionar, pero Nodus necesita modelos separados de extracción y síntesis para analizar el corpus.": "同期は機能しますが、Nodus ではコーパスを分析するために別個の抽出モデルと合成モデルが必要です。",
  "Generación de imágenes": "画像生成",
  "Configuración independiente para las imágenes decorativas opcionales. OpenAI usa su API oficial de imágenes y reutiliza la clave de OpenAI; Google reutiliza la clave de Gemini.": "オプションの装飾画像の独立した設定。 OpenAI は公式の画像 API を使用し、OpenAI キーを再利用します。 Google は Gemini キーを再利用します。",
  "Actualizar modelos": "モデルを更新する",
  "Estilo predeterminado": "デフォルトのスタイル",
  "Selección actual": "現在の選択内容",
  "Buscar por proveedor, nombre o identificador…": "プロバイダー、名前、または識別子で検索します…",
  "Proveedor y nombre": "プロバイダーと名前",
  "Orden alfabético": "アルファベット順",
  "Precio por imagen: menor a mayor (por proveedor)": "画像の価格: 低価格から高価格まで (プロバイダーごと)",
  "Precio por imagen: mayor a menor (por proveedor)": "画像の価格: 高から低 (プロバイダーごと)",
  "Como los proveedores publican tamaños y métricas diferentes, la ordenación por precio se aplica por separado dentro de cada proveedor. Los modelos sin precio directo quedan al final; no se estiman costes.": "プロバイダーはさまざまなサイズとメトリックを公開するため、価格の並べ替えは各プロバイダー内で個別に適用されます。直接価格のないモデルは最後に表示されます。コストは決して見積もられません。",
