  "Se realizará una nueva generación y puede producir un coste adicional. ¿Continuar?": "新しい世代が要求され、追加料金が発生する場合があります。続く？",
  "Eliminar imagen": "画像の削除",
  "La imagen se eliminará del almacenamiento local. El contenido principal no cambiará.": "画像はローカルストレージから削除されます。主な内容は変わりません。",
  "Generar inmersión": "イマージョンを生成",
  "Tu inmersión está lista": "イマージョンの準備ができました",
  "Puedes empezar ya: la imagen nunca bloquea el contenido.": "今すぐ始められます。画像がコンテンツをブロックすることはありません。",
  "Diseño": "デザイン",
  "Diseño de la imagen": "イメージデザイン",
  "Ajusta el estilo y la escena. Se genera una imagen nueva.": "スタイルやシーンに合わせて調整します。新しい画像が生成されます。",
  "Descripción de la escena": "シーンの説明",
  "Describe la escena que quieres ver. Si lo dejas vacío, se deduce del contenido.": "ご希望のシーンをご説明ください。空のままにすると、内容から推測されます。",
  "El estilo y las protecciones de «sin texto» se aplican automáticamente al generar.": "スタイルと「テキストなし」保護機能は、生成時に自動的に適用されます。",
  "La imagen aparecerá aquí una vez generada.": "画像が生成されると、ここに表示されます。",
  "Añadir imagen decorativa": "装飾画像を追加する",
