  "Cargado en memoria": "メモリにロードされました",
  "Ollama debe estar en marcha y los modelos descargados con \"ollama pull\". No requiere clave.": "Ollama を実行し、モデルを「ollam プル」で引っ張る必要があります。キーは必要ありません。",
  "Activa el servidor local en LM Studio (Developer → Start Server) y carga al menos un modelo. No requiere clave.": "LM Studio でローカルサーバーを起動し (「開発者」→「サーバーの起動」)、少なくとも1つのモデルをロードします。キーは必要ありません。",
  "Dirección del servidor (IP y puerto)": "サーバーアドレス (IP とポート)",
