  "Conectado{version} · {n} modelos disponibles": "接続済み{version} · {n}モデルが利用可能",
  "Sin conexión: {msg}": "接続されていません: {msg}",
  "•••••••• token guardado (opcional)": "•••••••• 保存されたトークン (オプション)",
  "token de acceso (opcional)": "アクセストークン(オプション)",
  "El servidor no reporta modelos. Descarga o carga uno primero.": "サーバーはモデルを報告しません。最初に1つをダウンロードまたはロードします。",
  "Proveedor local: no necesita clave. Usa la dirección por defecto; puedes cambiar IP y puerto en Ajustes → Proveedores.": "ローカルプロバイダー: キーは必要ありません。デフォルトのアドレスを使用します。 「設定」→「プロバイダー」で IP とポートを変更できます。",
  "Traducir": "翻訳する",
  "Traducciones": "翻訳",
  "Traducciones con IA": "AI翻訳",
  "Traduce este contenido a otro idioma. Cada idioma se guarda y puede regenerarse o eliminarse.": "このコンテンツを別の言語に翻訳してください。各言語は保存され、再生成または削除できます。",
  "Generar traducción": "翻訳を生成する",
  "Traduciendo…": "翻訳中…",
  "Genera la traducción con el modelo de IA configurado": "設定された AI モデルを使用して翻訳を生成します",
  "La traducción de un texto largo puede tardar. Puedes cerrar esta ventana: se guardará y aparecerá aquí al volver.": "長いテキストの翻訳には時間がかかる場合があります。このウィンドウは閉じても構いません。ウィンドウは保存され、戻ったときにここに表示されます。",
  "Cargando traducciones…": "翻訳を読み込み中…",
  "Aún no hay traducciones. Elige un idioma y genera la primera.": "まだ翻訳はありません。言語を選択し、最初の言語を生成します。",
  "Regenerar esta traducción": "この翻訳を再生成する",
  "Eliminar traducción": "翻訳の削除",
  "¿Eliminar la traducción a {lang}? Esta acción no se puede deshacer.": "{lang} 翻訳を削除しますか?これを元に戻すことはできません。",
  "Seleccionar todo": "すべて選択",
