  "Eliminar informes": "レポートの削除",
  "¿Eliminar {n} informes guardados? Esta acción no se puede deshacer.": "{n} 個の保存済みレポートを削除しますか?これを元に戻すことはできません。",
  "{n} informes eliminados.": "{n} 個のレポートが削除されました。",
  "Eliminar inmersiones": "イマージョンを削除",
  "¿Eliminar {n} inmersiones y todo su progreso? Esta acción no se puede deshacer.": "{n} 件のイマージョンと進捗をすべて削除しますか?この操作は元に戻せません。",
  "Nueva inmersión": "新しいイマージョン",
  "Domina un tema de tu corpus: panorama, estaciones con citas literales, contrastes, fronteras y examen final. Todo queda grabado para retomarlo.": "コーパスのテーマを習得: 概観、逐語引用を含むステーション、対比、境界、最終試験。すべて保存され、後で再開できます。",
  "Domina un tema de tu corpus: el contenido y el progreso se guardan para retomarlos; tus respuestas se borran al reiniciar.": "コーパスからトピックをマスターします。内容と進行状況は保存されるので再開できますが、再開すると回答はクリアされます。",
  "Buscar entre tus inmersiones…": "イマージョンを検索…",
  "Cargando inmersiones…": "イマージョンを読み込んでいます…",
  "Ninguna inmersión coincide con tu búsqueda.": "検索に一致するイマージョンはありません。",
  "Aún no hay inmersiones. Crea la primera y quedará aquí, con su progreso y tus respuestas, lista para retomarla.": "イマージョンはまだありません。最初のものを作成すると、進捗と回答とともにここに残り、いつでも再開できます。",
  "Aún no hay inmersiones. Crea la primera y quedará aquí, con su progreso, lista para retomarla.": "イマージョンはまだありません。最初のものを作成すると、進捗とともにここに残り、いつでも再開できます。",
  "Reiniciar borra las respuestas anteriores y comienza el recorrido desde el principio.": "再起動すると以前の回答がクリアされ、ルートが最初から始まります。",
  "Elige el tema y el alcance. Antes de generar verás qué sabe tu corpus (sin IA).": "トピックと範囲を選択します。生成する前に、コーパスが何を知っているかがわかります (AI はまだありません)。",
  "Duración": "間隔",
  "Novedades": "新着情報",
  "Esto es lo nuevo en esta versión de Nodus.": "Nodus のこのバージョンの新機能は次のとおりです。",
  "¡Entendido!": "わかった",
  "Plegar": "崩壊",
  "Desplegar": "拡大する",
  "Elige las colecciones a monitorizar. Despliega cualquier colección para elegir subcolecciones concretas si una es demasiado grande. Se incorporan metadatos; los análisis se lanzan manualmente salvo que actives automatización en Ajustes.": "監視するコレクションを選択します。コレクションが大きすぎる場合は、任意のコレクションを展開して特定のサブコレクションを選択します。メタデータがインポートされます。設定で自動化を有効にしない限り、分析は手動で実行されます。",
  "Fuentes primarias": "一次資料",
  "Genealogía": "系譜",
  "Bases de datos": "データベース",
  "próximamente": "近日公開",
