  "Vamos a crear tu primera bóveda": "最初のVaultをセットアップしましょう",
  "Ponle un nombre y elige su modo. El modo decide qué secciones verás y cómo trabaja la IA contigo; puedes crear más bóvedas, de otros modos, cuando quieras.": "名前を付けてモードを選択します。モードによって、表示されるセクションと AI がどのように連携するかが決まります。いつでも、他のモードでさらにVaultを作成できます。",
  "Después el asistente te ayudará a elegir su modelo de IA y su modelo de embeddings. Puedes cambiar el nombre en cualquier momento desde el selector de bóvedas.": "ウィザードは、AI モデルと埋め込みモデルの選択を支援します。Vaultの名前は、Vaultスイッチャーからいつでも変更できます。",
