  "Aún no hay personas. Se crean al analizar fuentes primarias o añadiéndolas a mano.": "まだ人がいません。これらは、一次ソースを分析するか、手動で追加するときに表示されます。",
  "sin fechas": "日付はありません",
  "Selecciona una persona para ver su ficha, sus eventos y la evidencia que la respalda.": "人物を選択すると、その人物の記録、出来事、その背後にある証拠が表示されます。",
  "Propuestos a partir de la evidencia de las fuentes. Tú confirmas; nada se añade al árbol solo.": "情報源の証拠に基づいて提案されています。あなたは確認します。ツリー自体には何も追加されません。",
