  "Extrae de 3 a 5 palabras clave separadas por comas. Devuelve solo las palabras clave.": "3 ～ 5個のキーワードをカンマ区切りで抽出します。キーワードのみを返します。",
  "Indica el sentimiento del contenido: positivo, negativo o neutro. Devuelve solo una palabra.": "コンテンツの感情を肯定的、否定的、または中立的に述べます。一言だけ返します。",
  "Traduce el contenido principal de esta fila al inglés. Devuelve solo la traducción.": "この行の主な内容を英語に翻訳してください。翻訳のみを返します。",
