  "Demo de bases de datos": "データベースのデモ",
  "Tres tablas de investigación con todos los tipos de columna, relaciones, registros, análisis, una conversación y notas de ejemplo. Incluye un tutorial guiado.": "すべての列タイプ、関係、記録、分析、会話、およびサンプルメモを含む3つの調査テーブル。ガイド付きチュートリアルが含まれています。",
  "Cargar demo de bases de datos": "データベースのロードのデモ",
  "Cargar datos de ejemplo": "サンプルデータをロードする",
  "Tutorial de bases de datos": "データベースのチュートリアル",
  "La lista de bases de datos, la tabla con columnas tipadas, la edición de celdas y las secciones de análisis y chat.": "データベースリスト、型指定された列を含むテーブル、セル編集、分析およびチャットセクション。",
  "Se mostrará el tutorial de bases de datos.": "データベースのチュートリアルが表示されます。",
  "Bienvenido al modo bases de datos": "データベースモードへようこそ",
  "Este es el modo bases de datos de Nodus: un gestor de tablas al estilo Notion, integrado en tu app. Te enseño en un minuto sus piezas con tres bases de datos de ejemplo ya cargadas. Puedes salir cuando quieras y volver a ver el tutorial desde Ajustes.": "これは Nodus のデータベースモードです。アプリに組み込まれた Notion スタイルのテーブルマネージャーです。すぐに、すでにロードされている3つのサンプルデータベースを使用して、その部分を説明します。いつでも終了して、[設定] からチュートリアルを再実行できます。",
  "Tus bases de datos": "あなたのデータベース",
  "En la barra lateral aparecen todas tus bases de datos. Cada una tiene un identificador único autogenerado. Pulsa una para abrirla, o el botón + para crear una nueva. Aquí abajo están también las secciones de Análisis y Chat.": "すべてのデータベースがサイドバーに表示されます。それぞれに自動生成された一意の ID があります。 1つをクリックして開くか、+ ボタンをクリックして新しいものを作成します。分析セクションとチャットセクションは以下のとおりです。",
  "La tabla": "テーブル",
  "Cada base de datos es una tabla de columnas tipadas: título, texto, número, fecha, hora, selección, selección múltiple y casilla. Arriba verás el número total de entradas y el porcentaje que suponen del total de todas tus bases de datos.": "各データベースは、タイトル、テキスト、番号、日付、時刻、選択、複数選択、チェックボックスなどの型付き列のテーブルです。上部には、エントリの合計数と、すべてのデータベースに占めるエントリの割合が表示されます。",
  "Edita directamente": "その場で編集",
  "Haz clic en cualquier celda para editarla al momento. Las columnas de selección muestran opciones con color que puedes añadir sobre la marcha; las casillas se marcan con un clic. Pasa el ratón por una fila para borrarla.": "任意のセルをクリックすると、すぐに編集できます。選択列には、その場で追加できる色分けされたオプションが表示されます。クリックするとチェックボックスが切り替わります。行を削除するには、行にマウスを移動します。",
  "Columnas a tu medida": "思い通りのコラム",
  "Pulsa la cabecera de una columna para renombrarla, cambiar su tipo o gestionar sus opciones, y usa el botón + del final de la cabecera para añadir nuevas columnas. Con «Nueva fila» añades registros.": "列ヘッダーをクリックして名前を変更したり、タイプを変更したり、オプションを管理したり、ヘッダーの末尾にある + を使用して新しい列を追加したりできます。 「新規行」でレコードを追加します。",
  "Análisis (próximamente)": "分析 (近日公開予定)",
  "Aquí podrás elegir una base de datos y obtener estadísticas automáticas más un informe con IA, con gráficos y el cálculo a la vista para que sea reproducible. Llega en una próxima fase.": "ここではデータベースを選択し、自動統計と AI レポートを取得します。グラフと計算が表示されるため、再現性が維持されます。後のフェーズに到着します。",
  "Chat de datos (próximamente)": "データチャット（近日公開予定）",
  "Un chat adaptado para conversar con una o varias de tus bases de datos, capaz de generar gráficos y consultas reproducibles. También llega en una próxima fase.": "1つまたは複数のデータベースと会話するように調整されたチャット。グラフや再現可能なクエリを生成できます。こちらも後のフェーズで登場します。",
  "Listo para tus datos": "データの準備ができました",
  "Esto es una demostración con datos de ejemplo. Cuando quieras empezar con los tuyos, crea una base de datos desde la barra lateral y añade tus columnas. Pronto podrás además importar CSV y subir archivos en masa.": "これはサンプルデータを使用したデモです。独自のデータベースを作成したい場合は、サイドバーからデータベースを作成し、列を追加します。まもなく、CSV のインポートやファイルの一括アップロードもできるようになります。",
