  "Nodus puede extraer conceptos, relaciones y citas textuales para crear el mapa de Ideas y el grafo de estudio.": "Nodus は、概念、関係、逐語的な引用を抽出して、アイデアマップと研究グラフを作成できます。",
  "El análisis se realizará en este dispositivo con el modelo seleccionado; el archivo no saldrá del equipo.": "分析は、選択したモデルを使用してこのデバイス上で実行されます。ファイルはこのコンピュータから離れることはありません。",
  "Se enviarán al proveedor indicado el título y el texto extraído necesario. El archivo original permanecerá en tu dispositivo.": "タイトルと必要な抽出テキストが指定されたプロバイダーに送信されます。元のファイルはデバイス上に残ります。",
