  "Heredar modelo principal": "プライマリモデルの継承",
  "Lleva tus notas, datos de estudio, materiales y grabaciones, borradores, búsquedas guardadas, auditorías de relaciones, bases de datos y Copias protegidas a otro equipo. Al importar se fusiona por fecha: gana la versión más reciente; las eliminaciones de Copias protegidas también se sincronizan mediante borrado lógico.": "メモ、研究データ、資料と記録、下書き、保存された検索、関係監査、データベース、および保護されたコピーを別のコンピューターに保存します。インポートは日付ごとにマージされます。最新バージョンが優先されます。保護コピーの削除は、論理的な削除によっても同期されます。",
  "Esta acción elimina datos de forma permanente. ¿Quieres continuar?": "この操作によりデータが完全に削除されます。続けますか?",
