  "Analíticas de estudio desactivadas": "研究分析が無効になっています",
  "Puedes activarlas en Ajustes → Modelos IA. Los repasos siguen funcionando localmente.": "[設定] → [AI モデル] で有効にできます。レビューは引き続きローカルで機能します。",
  "Modelos de IA": "AIモデル",
  "Un modelo general atiende conversación, análisis, resúmenes y las demás tareas de texto. Las capacidades especializadas se configuran debajo.": "1つの一般的なモデルは、会話、分析、要約、その他のテキストタスクを処理します。特殊な機能は以下で構成されます。",
  "El modelo general sigue siendo la base. Cada selector vacío hereda de él; los modelos de las herramientas se guardan solo en el vault actual.": "一般的なモデルがベースのままです。すべての空のセレクターはそれを継承します。ツールモデルは現在の Vault にのみ保存されます。",
  "Cada tarea utiliza el modelo concreto seleccionado. Los modelos de las herramientas se guardan solo en el vault actual.": "各タスクは、選択したモデルを使用します。ツールモデルは現在のVaultにのみ保存されます。",
  "Modelo general de texto": "一般的なテキストモデル",
  "Conversación, análisis, resúmenes y fallback de cualquier tarea sin modelo propio.": "独自のモデルを持たないあらゆるタスクの会話、分析、要約、フォールバック。",
  "Conversación, análisis, resúmenes y demás tareas de texto.": "会話、分析、要約、その他のテキストタスク。",
  "Este modelo consume la cuota de tu suscripción, no crédito de API. Un análisis completo del corpus puede agotar el límite semanal o mensual de tu plan.": "このモデルは、API クレジットではなく、サブスクリプション割り当てを利用します。完全なコーパス分析を行うと、プランの週次または月次の制限を使い果たす可能性があります。",
  "Este modelo local es de visión y no extrae ideas de forma fiable (tiende a divagar y no cerrar el JSON). Para extracción, elige Gemma 4 E2B u otro modelo mayor.": "このローカルモデルはビジョン指向であり、アイデアを確実に抽出しません (とりとめのない傾向があり、JSON を決して閉じない)。抽出には、Gemma 4 E2B またはそれ以上のモデルを選択してください。",
  "Estos pesos son los mismos que Nodus descarta entre sus modelos integrados: al extraer ideas divagan y no cierran el JSON. Puedes usarlos igualmente, pero para extracción conviene un modelo mayor.": "これらは、Nodus が組み込みモデルの間で除外する重みと同じです。アイデアを抽出するとき、それらはとりとめなく発生し、JSON を決して閉じません。これらを引き続き使用することはできますが、抽出にはより大きなモデルの方が適しています。",
  "El paso falló sin dejar un motivo. Reintenta; si vuelve a fallar, revisa el modelo en Ajustes → Modelos de IA.": "理由を記録せずにステップが失敗しました。再試行してください。再度失敗する場合は、「設定」→「AI モデル」でモデルを確認してください。",
  "Todavía no hay ningún modelo entre los que elegir. Pulsa «Cargar modelos» para ver los de tus proveedores, o marca los que quieras como favoritos en Ajustes → Proveedores de IA y modelos.": "まだ選択できるモデルがありません。 [モデルの読み込み] を押してプロバイダーが提供するモデルを表示するか、[設定] → [AI プロバイダーとモデル] で必要なモデルにスターを付けます。",
  "Sin respuesta de {list}. Revisa su clave o que el servidor local esté abierto.": "{list} からの応答がありません。そのキーを確認するか、ローカルサーバーが実行されていることを確認してください。",
  "solo visión": "ビジョンのみ",
  "Este modelo no puede usarse para extracción de ideas.": "このモデルはアイデア抽出には使用できません。",
  "Uso mi plan gratuito de este proveedor": "このプロバイダーの無料プランを使用しています",
  "Ajusta las peticiones a los límites del nivel gratuito (recorta la longitud de salida y espera si se alcanza el límite por minuto) para que el análisis no falle. Déjalo desmarcado si pagas por uso.": "分析が失敗しないように、リクエストを無料利用枠の制限に合わせて調整します (出力の長さをトリミングし、1分あたりの制限に達した場合は待機します)。使用ごとに支払う場合はチェックを外したままにしてください。",
