  "Eliminar modelo local": "ローカルモデルの削除",
  "Eliminar modelo": "モデルの削除",
  "Se eliminará «{model}» del almacenamiento de Nodus. Si está seleccionado, las funciones que lo usan dejarán de funcionar hasta que elijas otro modelo o vuelvas a descargarlo.": "「{model}」は Nodus ストレージから削除されます。これが選択されている場合、別のモデルを選択するか、再度ダウンロードするまで、それを使用する機能は動作しなくなります。",
  "Cambiar modelo de embeddings": "埋め込みモデルの変更",
  "Los embeddings creados con el modelo anterior no son compatibles con el nuevo. Nodus conservará los datos, pero tendrás que reindexar para que la búsqueda semántica y las relaciones usen el nuevo modelo. ¿Cambiar de todos modos?": "以前のモデルで作成された埋め込みは、新しいモデルと互換性がありません。 Nodus はデータを保持しますが、セマンティック検索とリレーションで新しいモデルを使用できるようにするには、インデックスを再作成する必要があります。とにかく変更しますか？",
  "Cambiar modelo": "機種変更",
  "Si cambias de modelo de embeddings, los vectores anteriores no servirán con el nuevo modelo y tendrás que reindexar.": "埋め込みモデルを変更すると、既存のベクトルは新しいモデルで機能しなくなるため、インデックスを再作成する必要があります。",
  "Embeddings multilingües de alta calidad para corpus amplios.": "大規模なコーパス向けの高品質な多言語埋め込み。",
  "Embeddings multilingües con contexto largo y buen equilibrio entre precisión y memoria.": "精度とメモリ使用量のバランスが取れたロングコンテキストの多言語埋め込み。",
  "Opción ligera y rápida para equipos con menos memoria.": "メモリの少ないコンピュータ向けの軽量かつ高速なオプションです。",
  "Modelo visual muy ligero para conversación, resúmenes e ideas.": "会話、要約、アイデアのための非常に軽量なビジョンモデル。",
  "Modelo visual de mayor calidad; requiere más almacenamiento y memoria.": "より多くのストレージとメモリを必要とする高品質ビジョンモデル。",
  "Modelo visual compacto orientado a documentos e imágenes.": "文書や画像向けに設計されたコンパクトなビジョンモデル。",
  "Guía esencial de Nodus e IA": "Nodus と AI の基本ガイド",
  "Bóvedas, modelos locales, API keys, costes, embeddings y voz explicados desde cero.": "Vault、ローカルモデル、API キー、コスト、埋め込み、音声について最初から説明します。",
