  "Las {count} preguntas generadas ya estaban en tu banco y se descartaron por duplicadas. Añade o cambia las fuentes, pide más preguntas, o elimina o archiva las anteriores.": "{count} で生成されたすべての質問はすでに銀行にあり、重複として破棄されました。ソースを追加または変更したり、さらに質問したり、既存のソースを削除またはアーカイブしたりできます。",
