  "Informes didácticos basados en tus materiales, apuntes y transcripciones indexados.": "インデックス付きの資料、メモ、トランスクリプトに基づいた、学習に焦点を当てたレポート。",
  "El informe enseña el tema paso a paso usando y citando tus materiales de estudio.": "レポートでは、教材を使用して引用しながら、トピックを段階的に説明します。",
  "Escribe el tema o pregunta que quieres comprender. El informe explicará los conceptos difíciles, ejemplos y conexiones usando tus materiales.": "理解したいトピックまたは質問を入力してください。レポートでは、難しい概念、例、接続について、資料を使用して説明します。",
  "Añadir entrada": "エントリを追加",
