  "Arrastra aquí cualquier tipo de archivo": "任意の種類のファイルをここにドラッグします",
  "Documentos, imágenes, audio, vídeo, datos o cualquier otro formato.": "ドキュメント、画像、オーディオ、ビデオ、データ、またはその他の形式。",
  "Examinar dispositivo": "デバイスを参照する",
  "Entrada sin archivo adjunto": "添付ファイルなしでのエントリー",
  "Ideal para transcripciones, testimonios, notas de investigación o referencias que todavía no tienen un archivo digital.": "まだデジタルファイルを持っていないトランスクリプト、証言、研究ノート、または参考文献に最適です。",
  "Buscar en Zotero…": "Zoteroを検索…",
  "No se encontraron elementos.": "項目が見つかりませんでした。",
  "Este elemento no tiene archivos adjuntos.": "この商品には付属品はありません。",
  "6. Texto o transcripción": "6. テキストまたは転写",
  "Opcional. Añade una transcripción o texto que deba ser buscable e indexado…": "オプション。検索可能でインデックス付けされるトランスクリプトまたはテキストを追加します…",
  "Si el archivo permite extraer texto automáticamente, Nodus lo hará al guardarlo. Este campo permite añadirlo o sustituirlo manualmente.": "ファイルからテキストを自動的に抽出できる場合、Nodus は保存時に抽出します。このフィールドを使用すると、手動で追加または置換できます。",
  "Guardar entrada": "エントリを保存する",
  "Ideas de estudio": "研究のアイデア",
  "Grafo de estudio": "スタディグラフ",
  "Buscando actualizaciones…": "アップデートをチェック中…",
  "Actualización {version} encontrada. La descarga empezará automáticamente.": "更新 {version} が見つかりました。ダウンロードが自動的に開始されます。",
  "Descargando actualización… {percent}%": "アップデートをダウンロード中… {percent}%",
  "Actualización {version} descargada. Reiniciando para instalarla…": "アップデート {version} がダウンロードされました。インストールするために再起動しています…",
  "Instalando Nodus {version} y reiniciando…": "Nodus {version} をインストールして再起動しています…",
