  "{n} con vídeo": "{n} ビデオ付き",
  "Selecciona una presentación": "プレゼンテーションを選択してください",
  "Elige una presentación de la lista para ver sus diapositivas, o importa un PDF nuevo.": "リストからプレゼンテーションを選択してスライドを表示するか、新しい PDF をインポートします。",
  "Eliminar presentación": "プレゼンテーションの削除",
  "¿Seguro que quieres eliminar «{name}»? Esta acción no se puede deshacer.": "「{name}」を削除してもよろしいですか?この操作は元に戻すことができません。",
