  "Vídeos": "動画",
  "Tiene notas": "メモあり",
  "Tiene vídeo": "ビデオあり",
  "Añadido recientemente": "最近追加された",
  "Abierto recientemente": "最近オープンした",
  "Diapositiva {n} de {total}": "{total} の {n} をスライドします",
  "El PowerPoint tiene {pptx} diapositivas y el PDF tiene {pdf}. Deben coincidir para importar las notas.": "PowerPoint には {pptx} 個のスライドがあり、PDF には {pdf} 個のスライドがあります。メモをインポートするには、それらが一致する必要があります。",
  "El número de diapositivas no coincide": "スライド数が合わない",
  "Escribe las notas de la diapositiva {n}…": "スライド {n} のメモを書きます…",
  "Importar notas (.pptx)": "メモ (.pptx) をインポートする",
  "Importar notas (.txt)": "メモ (.txt) をインポートする",
  "No se pudieron exportar las notas a TXT.": "ノートをTXTにエクスポートできませんでした。",
  "El TXT tiene {txt} diapositivas y el PDF tiene {pdf}. Deben coincidir para importar las notas.": "TXT ファイルには {txt} 個のスライドがあり、PDF には {pdf} 個のスライドがあります。メモをインポートするには、それらが一致する必要があります。",
  "El archivo TXT de notas no tiene un formato válido.": "メモの TXT ファイルは有効な形式ではありません。",
  "Notas del presentador": "講演者のメモ",
  "Notas importadas": "インポートされたメモ",
