  "Esta entrada todavía no existe": "このエントリはまだ存在しません",
  "Crear la entrada «{name}»": "エントリ「{name}」を作成します",
  "Los artículos son para lo que no es un personaje, un lugar ni una facción: la magia, una religión, una lengua, una criatura, un objeto. Todo lo demás ya está en la enciclopedia por sí solo.": "記事は、キャラクター、場所、派閥以外のもの、つまり魔法、宗教、言語、生き物、物体を対象としています。それ以外のものはすべて、すでに百科事典に単独で載っています。",
  "Nuevo artículo": "新しい記事",
  "Todavía nadie ha definido esto. Al crearlo, todas las menciones que lo esperaban quedarán enlazadas.": "まだ誰もこれを定義していません。これを作成すると、それを待っていたすべてのメンションがリンクされます。",
  "Escribe [[ para enlazar con cualquier cosa del mundo": "[[ と入力して世界中のあらゆるものにリンクします",
  "Escribe la entrada…": "エントリーを書いて…",
  "Creada y enlazada.": "作成してリンクしました。",
  "Creada. {count} menciones enlazadas.": "作成されました。 {count} の言及がリンクされています。",
  "Eliminar la entrada": "エントリを削除する",
  "Escribiendo…": "書き込み…",
  "Esta ficha aún no tiene texto. Se escribe en su propia sección.": "このシートにはまだテキストがありません。それは独自のセクションに書かれています。",
  "Ficha completa": "フルシート",
  "Las menciones que la enlazaban no se borran: quedarán marcadas como pendientes.": "リンクされているメンションは削除されず、保留中としてマークされます。",
  "Mencionada en": "で言及",
  "No hay bastante material todavía: escribe un resumen o enlaza algo.": "まだ十分な資料がありません。概要を書くか、リンクを貼ってください。",
  "Propuesta de la IA": "AI提案",
  "Relacionados": "関連している",
  "Todavía no hay nada escrito aquí.": "ここにはまだ何も書かれていません。",
  "Buscar en todo el mundo…": "世界中を検索してください…",
  "Buscar «{query}» en el texto completo": "「{query}」を全文検索",
  "Con texto": "書かれた",
  "Este mundo todavía está vacío.": "この世界はまだ空っぽです。",
  "Ninguna entrada coincide con el filtro.": "フィルタに一致するエントリはありません。",
  "Sin desarrollar": "未開発",
  "Tipo de entrada": "エントリータイプ",
  "{count} en el texto completo": "全文中の {count}",
  "«{query}» no aparece en ningún texto del mundo.": "「{query}」はこの世界のどの文章にも登場しません。",
  "reglas del mundo, conflictos, arcos narrativos, consistencia, preguntas abiertas, tramas y manuscritos": "世界ルール、紛争、ストーリーアーク、一貫性、未解決の質問、プロットと原稿",
  "En la enciclopedia": "百科事典では",
  "{count} sin desarrollar": "{count} 未開発",
  "Construye un mundo de ficción pieza a pieza: personajes, lugares, facciones, culturas, escenas y mapas. La enciclopedia los reúne todos en un solo índice y te deja escribir el resto del mundo —la magia, una religión, una lengua— enlazándolo con [[dobles corchetes]].": "キャラクター、場所、派閥、文化、シーン、マップなど、架空の世界を少しずつ構築していきます。百科事典はそれらすべてを1つの索引に集め、世界の残りの部分 (魔法、宗教、言語) を [[二重括弧]] でリンクして書くことができます。",
  "Analizar el mundo": "世界を分析する",
  "Aparecen a menudo y no están definidos": "それらは頻繁に登場しますが、定義されていません",
  "Esto es una sospecha, no un hecho: son nombres que se repiten en tus textos.": "これは直感であり、事実ではありません。これらの名前はテキスト内で繰り返し出てきます。",
  "Lo escribiste tú entre dobles corchetes, así que ya existen en tu mundo.": "これらは二重括弧内に自分で書いたものなので、すでにあなたの世界に存在しています。",
  "Lo que falta por definir": "まだ未定",
  "Los enlazaste y no existen": "あなたはそれらをリンクしましたが、それらは存在しません",
  "Nada pendiente: todo lo que el mundo nombra tiene entrada.": "保留中のものは何もありません。ワールドの名前が付けられているものはすべてエントリがあります。",
  "«{name}» creada y enlazada.": "「{name}」が作成され、リンクされました。",
