  "Instalación sencilla y actualizaciones automáticas.": "簡単なインストールと自動アップデート。",
  "Instalar desde Chrome Web Store": "Chrome ウェブストアからインストールする",
  "Alternativa manual para desarrollo o pruebas. Descomprime el ZIP y cárgalo desde chrome://extensions.": "開発またはテストのための手動による代替。 ZIP を抽出し、chrome://extensions からロードします。",
  "Revocar navegadores emparejados": "ペアリングされたブラウザを取り消す",
