  "Chrome no permite que una app instale extensiones silenciosamente. Descarga el ZIP, descomprímelo y usa Cargar descomprimida en chrome://extensions.": "Chrome では、アプリが拡張機能をサイレントにインストールすることはできません。 ZIP をダウンロードして解凍し、chrome://extensions で展開されたロードを使用します。",
