  "Nodus Browser no abre este tipo de dirección": "Nodus Browser はこの種のアドレスを開きません",
  "Esta página dejó de responder": "このページは応答を停止しました",
  "Ojo: si entras en tu navegador, la sesión se queda allí. Seguirás sin haber iniciado sesión en {host} dentro de Nodus, porque las cookies no se comparten entre navegadores.": "注: ブラウザでサインインすると、セッションはそこに残ります。 Cookie はブラウザ間で共有されないため、Nodus 内では {host} からサインアウトしたままになります。",
  "Ojo: si entras en tu navegador, la sesión se queda allí. Seguirás sin haber iniciado sesión en Google dentro de Nodus, porque las cookies no se comparten entre navegadores.": "注: ブラウザでサインインすると、セッションはそこに残ります。 Cookie はブラウザ間で共有されないため、Nodus 内では Google からサインアウトしたままになります。",
  "Si {host} admite entrar con contraseña o con un enlace por correo, esa vía sí funciona aquí dentro, y Nodus recordará la sesión.": "{host} がパスワードまたは電子メールリンクを受け入れる場合、そのルートはここで機能し、Nodus はセッションを記憶します。",
  "Volver e intentar con contraseña": "戻ってパスワードを試してください",
  "Usar {host} en mi navegador": "ブラウザで {host} を使用してください",
  "Para que Nodus lea tu Gmail o tu Drive haría falta otra cosa: conectar la cuenta desde Ajustes, que es la vía que Google sí admite para aplicaciones de escritorio. Todavía no está disponible.": "Nodus が Gmail やドライブを読み取るには、別の操作が必要になります。それは、Google がデスクトップアプリケーションに対して許可しているルートである、[設定] からアカウントに接続することです。まだ利用できません。",
  "No es un fallo de Nodus: Google rechaza el inicio de sesión desde cualquier navegador incrustado en otra aplicación.": "これは Nodus のせいではありません。Google は、別のアプリケーションに埋め込まれたブラウザからのサインインを拒否します。",
  "Google no permite iniciar sesión desde un navegador integrado": "Google は埋め込みブラウザからのサインインを許可していません",
  "Abrir en tu navegador": "ブラウザで開く",
  "No se pudo cargar la página": "ページを読み込めませんでした",
  "Denegar": "拒否",
  "Denegar siempre": "常に否定する",
  "Permitir": "許可する",
  "Permitir siempre": "常に許可する",
  "quiere usar la cámara y el micrófono.": "カメラとマイクを使用したいと考えています。",
  "quiere usar la cámara.": "カメラを使いたいと思っています。",
