  "quiere usar la cámara o el micrófono.": "カメラまたはマイクを使用したい。",
  "quiere conocer tu ubicación.": "あなたの位置を知りたいと思っています。",
  "pide un permiso adicional.": "追加の許可を要求しています。",
  "La conexión con este sitio no es privada": "このサイトへの接続はプライベートではありません",
  "Chromium no pudo verificar que «{host}» sea quien dice ser. Puede tratarse de un certificado caducado o mal configurado, o de que alguien esté interceptando la conexión.": "Chromium は、«{host}” が本人であることを確認できませんでした。証明書の有効期限が切れているか設定が間違っているか、何者かが接続を傍受している可能性があります。",
  "Nodus Browser no ofrece continuar de todos modos: no valida certificados por su cuenta, así que no puede contradecir ese veredicto.": "Nodus Browser にはとにかく続行する方法がありません。Nodus Browser 自体は証明書を検証しないため、その判定を覆すことはできません。",
