  "Antes de cambiar el esquema, Nodus conserva una copia inmutable y verificada. Puedes abrirla como un vault separado sin sustituir el actual.": "スキーマを変更する前に、Nodus は不変の検証済みコピーを保持します。現在のVaultを置き換えずに、別のVaultとして開くことができます。",
