  "Reparando": "修理",
  "Publicando": "出版",
  "El texto disponible ha cambiado. Se conserva el análisis anterior hasta completar un reescaneo.": "使用できるテキストが変更されました。以前の分析は、再スキャンが完了するまで保持されます。",
  "El adjunto existe en Zotero, pero el archivo ya no está en su ubicación original.": "添付ファイルは Zotero に存在しますが、ファイルは元の場所にありません。",
  "El PDF está escaneado y no tiene capa de texto. Activa OCR y vuelve a analizar.": "PDF はスキャンされており、テキストレイヤーがありません。 OCRを有効にして再度分析してください。",
  "El adjunto no produjo texto utilizable. Revisa el archivo o activa OCR.": "添付ファイルからは使用可能なテキストが生成されませんでした。ファイルを確認するか、OCR を有効にしてください。",
