  "Incluye metadatos, extractos y análisis; nunca archivos originales, rutas locales ni datos privados.": "メタデータ、抜粋、分析が含まれます。オリジナルのファイル、ローカルパス、プライベートデータは決して使用しないでください。",
  "Publicar testimonios textuales": "証言原文を公開する",
  "Incluye entrevistas, transcripciones y análisis; participantes, acuerdos y archivos multimedia permanecen privados.": "インタビュー、トランスクリプト、分析が含まれます。参加者、合意、メディアファイルは非公開のままです。",
