  "Organiza el trabajo del corpus": "コーパス作業を整理する",
  "Ya hay suficientes ideas y fuentes para organizar notas y borradores con citas verificables en un único espacio de trabajo.": "検証可能な引用を含むメモや下書きを1つのワークスペースに整理するのに十分なアイデアとソースがあります。",
