  "El Espacio de trabajo reúne notas, borradores y organización en una única superficie. Conserva las citas clicables y permite estructurar el manuscrito sin separar artificialmente Escritura y Proyectos.": "ワークスペースは、メモ、下書き、整理を1つの面にまとめます。引用をクリックしやすくし、執筆とプロジェクトを人為的に分離することなく原稿を構造化できます。",
